// ===== src/worker/layout.js ===================================================================================

// How a tiddler is stored, and how a save is read (design 1.2).
//
// Every tiddler is stored "flat": every field at the top level, compact JSON, "text" last, then the
// worker's revision, bag and recipe; customMetadata { revision, layout: "flat" }. The conflict guard
// (src/browser/conflict-guard.js) sends exactly that, without revision, bag or recipe (header
// X-Tiddler-Layout: flat): the worker parses only the fields before "text" and appends its own,
// working on the raw bytes, so the text itself (a whole plugin, an image...) is never decoded, parsed
// or re-encoded. Anything else, such as TiddlyWeb JSON (custom fields under "fields", the text
// anywhere) from a tab without the module, is parsed and turned into the flat layout first. Reading
// a stored object back uses the same layout: its fields come before "text", so usually only the
// start of the object is read.


const FLAT_LAYOUT = "flat";

const TEXT_KEY = encoder.encode(',"text":');

// Where ',"text":' starts in a flat body. Inside a JSON string every quote is escaped, so this
// sequence can only be the "text" key itself.
function textKeyOffset(bytes) {
  for (let i = bytes.indexOf(TEXT_KEY[0]); i !== -1; i = bytes.indexOf(TEXT_KEY[0], i + 1)) {
    if (TEXT_KEY.every((byte, j) => bytes[i + j] === byte)) return i;
  }
  return -1;
}

// A save whose body isn't a tiddler: answered 400, nothing stored
class BadSave extends Error {}

function isTiddlerObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value) && typeof value.title === "string";
}

function parseJsonBody(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    throw new BadSave(`the body is not JSON (${e.message})`);
  }
}

// TiddlyWiki's field values are text, or lists of text (tags). An object can't be stored flat (a
// "text" key inside it would be taken for the tiddler's text), with one exception: a field called
// "fields" stays nested as { fields: value }, the way TiddlyWeb's layout has it, because a flat
// "fields" is where TiddlyWiki's loader looks for nested custom fields.
function isFieldValue(value) {
  return typeof value === "string" || (Array.isArray(value) && value.every(item => typeof item === "string"));
}

function isStorable(name, value) {
  if (name !== "fields") return isFieldValue(value);
  return value !== null && typeof value === "object" && !Array.isArray(value) && Object.keys(value).length === 1 &&
    Object.hasOwn(value, "fields") && typeof value.fields === "string";
}

// TiddlyWiki unpacks that nested "fields" when it loads a tiddler through sync, but not the tiddlers
// the page hands it at boot (preloadTiddlers): the page build unpacks those
function hasNestedFields(tiddler) {
  return isStorable("fields", tiddler.fields);
}

const BOOKKEEPING = ["text", "revision", "bag", "recipe"];

// The fields before "text" of a body in the flat layout, or null if it isn't one
function flatFields(bytes, end) {
  if (bytes[0] !== 0x7b || bytes[end - 1] !== 0x7d) return null;
  let cut = textKeyOffset(bytes);
  if (cut === -1) cut = end - 1;   // no text: the fields run up to the closing brace
  else if (!textIsLast(bytes, cut + TEXT_KEY.length, end)) return null;
  if (cut <= 0) return null;
  let fields = null;
  try { fields = JSON.parse(decoder.decode(bytes.subarray(0, cut)) + "}"); } catch (e) { return null; }
  // Pretty-printed, with these before "text", or with a value that isn't text: not the flat layout after all
  if (!isTiddlerObject(fields) || BOOKKEEPING.some(name => Object.hasOwn(fields, name)) ||
      !Object.entries(fields).every(([name, value]) => isStorable(name, value))) return null;
  return fields;
}

// Whether the text, from its opening quote at start, is a string that ends the body (end - 1 is its
// closing brace), as the flat layout has it: it opens with a quote, and the body ends with one that
// isn't escaped. Up to FLAT_CHECK_BYTES, also that no other field follows: the first quote that isn't
// escaped (inside a JSON string, every quote is) must be that last one. A bigger body (a plugin) isn't
// scanned: it costs milliseconds of CPU a megabyte, and the conflict guard always puts the text last.
// Otherwise the body is read in full (toFlat).
const FLAT_CHECK_BYTES = 256 * 1024;

function textIsLast(bytes, start, end) {
  const close = end - 2;
  if (bytes[start] !== 0x22 || close <= start || bytes[close] !== 0x22) return false;
  const escaped = at => {
    let slashes = 0;
    while (bytes[at - 1 - slashes] === 0x5c) slashes++;
    return slashes % 2 === 1;
  };
  if (escaped(close)) return false;
  if (end > FLAT_CHECK_BYTES) return true;
  let i = bytes.indexOf(0x22, start + 1);
  while (i !== -1 && i < close && escaped(i)) i = bytes.indexOf(0x22, i + 1);
  return i === close;
}

// Any other tiddler JSON, TiddlyWeb's layout included, turned into the flat layout
function toFlat(tiddler) {
  // A title that isn't text would make the tiddler list unreadable (and no browser sends one)
  if (!isTiddlerObject(tiddler)) throw new BadSave("the body is not a tiddler (a JSON object with a text title)");
  let { fields: custom = {}, text, revision, bag, recipe, ...fields } = tiddler;
  if (text !== undefined && typeof text !== "string") throw new BadSave('the field "text" isn\'t text');
  // In TiddlyWeb's layout, "fields" holds the custom fields (text there is a field called "fields")
  if (custom === null) custom = {};
  else if (typeof custom !== "object") custom = { fields: custom };
  else if (Array.isArray(custom)) throw new BadSave('"fields" must hold the custom fields');
  for (const [name, value] of Object.entries(custom)) {
    if (!Object.hasOwn(fields, name) && !BOOKKEEPING.includes(name)) fields[name] = value;
  }
  if (Object.hasOwn(fields, "fields")) fields.fields = { fields: fields.fields };   // see isStorable
  const notText = Object.keys(fields).find(name => !isStorable(name, fields[name]));
  if (notText !== undefined) throw new BadSave(`the field "${notText}" isn't text`);
  return { fields, bytes: encoder.encode(JSON.stringify(text === undefined ? fields : { ...fields, text })) };
}

// Returns { fields, stored(revision) }: fields = the tiddler without its text, stored(revision) =
// the bytes to store, with the worker's revision, bag and recipe
async function readSave(request) {
  let bytes = new Uint8Array(await request.arrayBuffer());
  let end = bytes.length;
  while (end > 0 && bytes[end - 1] <= 0x20) end--;
  let fields = request.headers.get("X-Tiddler-Layout") === FLAT_LAYOUT ? flatFields(bytes, end) : null;
  if (!fields) {
    ({ fields, bytes } = toFlat(parseJsonBody(decoder.decode(bytes))));
    end = bytes.length;
  }
  return flatSave(fields, bytes.subarray(0, end));
}

// A save from its fields and its body in the flat layout (ending with "}")
function flatSave(fields, body) {
  return {
    fields,
    body,
    stored: revision => concatBytes([body.subarray(0, body.length - 1), storedSuffix(revision)])
  };
}

// What the worker appends to a stored tiddler, after its text
function storedSuffix(revision) {
  return encoder.encode(`,"revision":"${revision}","bag":"default","recipe":"default"}`);
}

// A tiddler TiddlyWiki has only the fields of (from the tiddler list; the text loads separately) is
// marked _is_skinny. Changed before its text arrives (a checkbox clicked during the first sync, say),
// it's saved without the text: the stored text is kept, as TiddlyWiki's own server does, rather than
// stored as nothing, and the mark isn't stored. A text sent with the mark was typed into the empty
// editor of such a tiddler (opened offline, say, limits 5: TiddlyWiki's draft copies the mark, and
// the editor starts empty): it's what was meant, and is stored as sent; only a save without a text,
// or with an empty one, keeps the stored text. current: the stored object, read with its body.
async function keepStoredText(save, current) {
  const { _is_skinny, ...fields } = save.fields;
  const head = encoder.encode(JSON.stringify(fields));
  const at = textKeyOffset(save.body);
  const typed = at === -1 ? null : save.body.subarray(at, save.body.length - 1);   // ',"text":"..."' as sent
  if (typed && typed.length > TEXT_KEY.length + 2) {   // more than ,"text":""
    return flatSave(fields, concatBytes([head.subarray(0, head.length - 1), typed, encoder.encode("}")]));
  }
  let text = new Uint8Array(0);   // ',"text":"..."' of the stored tiddler
  if (current) {
    const stored = new Uint8Array(await current.arrayBuffer());
    const at = textKeyOffset(stored), suffix = storedSuffix(revisionOf(current));
    const tail = stored.subarray(stored.length - suffix.length);
    if (at !== -1 && suffix.every((byte, i) => tail[i] === byte)) {
      text = stored.subarray(at, stored.length - suffix.length);   // the stored layout: copied as bytes
    } else {
      // Stored by hand: read as JSON
      let value;
      try { value = JSON.parse(decoder.decode(stored)).text; } catch (e) {}
      if (typeof value === "string") text = encoder.encode(`,"text":${JSON.stringify(value)}`);
    }
  }
  return flatSave(fields, concatBytes([head.subarray(0, head.length - 1), text, encoder.encode("}")]));
}

// Whether the stored object holds exactly what this save would store with that revision
// (current: the object as head() returned it)
async function storesSameContent(env, current, save, revision) {
  const wouldStore = save.stored(revision);
  // Different sizes, different content: no need to read it (a real conflict, nearly always)
  if (current.size !== wouldStore.length) return false;
  const obj = await env.WIKI_BUCKET.get(current.key);
  if (!obj) return false;
  const stored = new Uint8Array(await obj.arrayBuffer());
  if (stored.length !== wouldStore.length) return false;
  for (let i = 0; i < stored.length; i++) {
    if (stored[i] !== wouldStore[i]) return false;
  }
  return true;
}

const HEAD_BYTES = 16384;

// The fields of a stored tiddler (not its text), or null: only its beginning is read, unless the
// fields are longer. item: the object as listed or looked up (key, size)
async function storedFields(env, item) {
  if (item.customMetadata?.layout !== FLAT_LAYOUT) return null;
  const read = await readStoredFields(env, item);
  const fields = read && read.fields;
  return fields !== null && typeof fields === "object" && !Array.isArray(fields) ? fields : null;
}

// { fields (null if they can't be read), obj }, or null if it's gone
async function readStoredFields(env, item) {
  const partial = item.size > HEAD_BYTES;
  let obj = await env.WIKI_BUCKET.get(item.key, partial ? { range: { offset: 0, length: HEAD_BYTES } } : undefined);
  if (!obj) return null;   // deleted meanwhile
  let bytes = new Uint8Array(await obj.arrayBuffer());
  let cut = textKeyOffset(bytes);
  if (partial && cut === -1) {   // fields over HEAD_BYTES, or no text: read whole
    obj = await env.WIKI_BUCKET.get(item.key);
    if (!obj) return null;
    bytes = new Uint8Array(await obj.arrayBuffer());
    cut = textKeyOffset(bytes);
  }
  let fields = null;
  try { fields = JSON.parse(cut === -1 ? decoder.decode(bytes) : decoder.decode(bytes.subarray(0, cut)) + "}"); } catch (e) {}
  if (fields && typeof fields === "object") delete fields.text;
  return { fields, obj };
}

// ===== src/worker/backup/github.js ============================================================================

// GitHub's Contents API (one file per tiddler, tiddlers/<title>.json, one commit per version), what
// its answers mean, and how long to wait after a failure.


// Writes bytes as base64 into out (ASCII bytes) from position at; returns where it ends. GitHub takes
// a file's content in base64, in a request body sent as bytes: written there directly, never as a
// string of the whole. (Through one, with String.fromCharCode, btoa, then the body encoded to be
// sent, a 1.5 MB plugin took about 7 ms of CPU; the loop below about 2: a run gets about 10 on the
// free plan.) The runtime's own encoder, where it has one (Uint8Array.prototype.toBase64, native in
// V8 and in Workers; not in Node 22, where test/cpu.test.mjs measures the loop), halves that again,
// and more on its first run in a fresh isolate, where the loop isn't optimised yet: in slices of 3 MB
// (a multiple of 3, so no padding inside; a string of 4 MB at most beside the body, where the whole
// at once would take a 30 MB plugin's run past the isolate's 128 MB), each written into the body as
// it comes. The same bytes either way (test/cpu.test.mjs checks, in the Workers runtime).
const BASE64_DIGITS = encoder.encode("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/");
const BASE64_SLICE = 3e6;
const nativeBase64 = typeof Uint8Array.prototype.toBase64 === "function";

function writeBase64(bytes, out, at) {
  if (nativeBase64) {
    for (let i = 0; i < bytes.length; i += BASE64_SLICE) {
      at += encoder.encodeInto(bytes.subarray(i, Math.min(i + BASE64_SLICE, bytes.length)).toBase64(), out.subarray(at)).written;
    }
    return at;
  }
  const end = bytes.length - bytes.length % 3;
  let i = 0;
  for (; i < end; i += 3) {
    const v = bytes[i] << 16 | bytes[i + 1] << 8 | bytes[i + 2];
    out[at] = BASE64_DIGITS[v >>> 18];
    out[at + 1] = BASE64_DIGITS[v >>> 12 & 63];
    out[at + 2] = BASE64_DIGITS[v >>> 6 & 63];
    out[at + 3] = BASE64_DIGITS[v & 63];
    at += 4;
  }
  if (i < bytes.length) {
    // One or two bytes left: padded with "="
    const two = i + 1 < bytes.length;
    const v = bytes[i] << 16 | (two ? bytes[i + 1] << 8 : 0);
    out[at] = BASE64_DIGITS[v >>> 18];
    out[at + 1] = BASE64_DIGITS[v >>> 12 & 63];
    out[at + 2] = two ? BASE64_DIGITS[v >>> 6 & 63] : 61;
    out[at + 3] = 61;
    at += 4;
  }
  return at;
}

// Git's blob id for a file (its bytes), to recognise content GitHub already has
async function gitBlobSha(content) {
  const header = encoder.encode(`blob ${content.length}\0`);
  const data = new Uint8Array(header.length + content.length);
  data.set(header);
  data.set(content, header.length);
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-1", data));
  return Array.from(digest, b => b.toString(16).padStart(2, "0")).join("");
}

// A failed GitHub call; retryAfter (seconds) is set when GitHub says how long to wait, status is
// GitHub's HTTP status
class GitHubError extends Error {
  // detail: GitHub's own message ("Bad credentials"), when its answer has one
  constructor(message, retryAfter, status, detail = "") {
    super(message);
    this.name = "GitHubError";
    this.retryAfter = retryAfter;
    this.status = status;
    this.detail = detail;
  }
}

// GitHub Contents API, with the same file paths as the original per-save backup. counter: an object
// whose .calls is increased by one per call made, for a run's budget (queue.js)
function githubContents(env, counter) {
  const { repo, token, branch } = github(env);
  const headers = {
    Authorization: `Bearer ${token}`,
    Accept: "application/vnd.github.v3+json",
    "Content-Type": "application/json",
    "X-GitHub-Api-Version": "2022-11-28",
    "User-Agent": "TiddlyWiki-Cloudflare-Worker"
  };
  // body: the request body, as text or bytes
  async function call(method, title, body) {
    const apiBase = `https://api.github.com/repos/${repo}/contents/tiddlers/${encodeURIComponent(title)}.json`;
    // Reads ask for the "object" format: the default one isn't available for files between 1 and
    // 100 MB, so their backups would fail forever and hold up every later one. The object format
    // works for all sizes, with empty content above 1 MB.
    return request(method, method === "GET" ? `${apiBase}?ref=${branch}` : apiBase, method === "GET" ? { ...headers, Accept: "application/vnd.github.object+json" } : headers, body);
  }
  async function request(method, url, requestHeaders, body) {
    if (counter) counter.calls = (counter.calls || 0) + 1;
    const res = await fetch(url, { method, headers: requestHeaders, body });
    if (method === "GET" && res.status === 404) return null;
    if (!res.ok) {
      // How long GitHub asks us to wait, if it says (rate limits)
      let waitSeconds;
      const retryAfter = parseInt(res.headers.get("retry-after"), 10);
      const reset = parseInt(res.headers.get("x-ratelimit-reset"), 10);
      if (retryAfter > 0) waitSeconds = retryAfter;
      else if (res.headers.get("x-ratelimit-remaining") === "0" && reset) waitSeconds = Math.max(reset - Date.now() / 1000, 1);
      const answer = await res.text();
      let detail = "";
      try {
        detail = String(JSON.parse(answer).message || "");
      } catch {}
      throw new GitHubError(`GitHub ${method} ${res.status}: ${answer.slice(0, 200)}`, waitSeconds, res.status, detail);
    }
    return res.json();
  }
  return {
    // { sha } of the file on GitHub, or null. (GitHub sends the content too, up to 1 MB; it isn't used.)
    async get(title) {
      const file = await call("GET", title);
      return file ? { sha: file.sha } : null;
    },
    // content: bytes. Returns the new blob sha. (The body is made as bytes, the content written into
    // it as base64: see writeBase64.)
    async put(title, content, message, sha) {
      const head = encoder.encode(`{"message":${JSON.stringify(message)},"branch":${JSON.stringify(branch)}${sha ? `,"sha":${JSON.stringify(sha)}` : ""},"content":"`);
      const body = new Uint8Array(head.length + Math.ceil(content.length / 3) * 4 + 2);
      body.set(head);
      const end = writeBase64(content, body, head.length);
      body[end] = 34;        // "
      body[end + 1] = 125;   // }
      const result = await call("PUT", title, body);
      return result.content.sha;
    },
    async remove(title, sha, message) {
      await call("DELETE", title, JSON.stringify({ message, sha, branch }));
    },
    // Every tiddler file of the branch, in one call (the Git Trees API, the whole tree at once): the
    // titles and blob shas of tiddlers/<title>.json, subdirectories included (titles with slashes);
    // none for a branch with no commits yet; null if the tree is too big for one answer (GitHub
    // truncates past 100,000 entries or 7 MB)
    async tiddlerFiles() {
      const tree = await request("GET", `https://api.github.com/repos/${repo}/git/trees/${encodeURIComponent(branch)}?recursive=1`, headers);
      if (!tree) return [];
      if (tree.truncated) return null;
      const files = [];
      for (const entry of tree.tree || []) {
        if (entry.type === "blob" && typeof entry.path === "string" && entry.path.startsWith("tiddlers/") && entry.path.endsWith(".json")) {
          files.push({ title: entry.path.slice("tiddlers/".length, -".json".length), sha: entry.sha });
        }
      }
      return files;
    }
  };
}

const BACKUP_MAX_DELAY = 6 * 3600;

// GitHub refusing every backup, not one file: the token (401: expired or revoked; 403 other than a
// rate limit: no access to the repository, or the repository archived), or the repository not
// found (404: only on a write, as the 404 of a read, a file not there yet, isn't an error). A 403 or
// 404 could still concern one file only (a path GitHub can't take): it pauses every backup only once
// a second tiddler gets one in the same run, or one file would hold up all the others (the oldest
// backup tries first after a pause). Until then it's that file's own failure.
function isAccountWide(e) {
  return e.status === 401 || (e.status === 403 && !isRateLimit(e)) || e.status === 404;
}

// GitHub refusing this file for good: its path, or its content (a secret in it, which its push
// protection refuses with a 409; a 409 that's only a race over the file's sha passes on its retry)
function isRefusal(e) {
  return e.status === 409 || e.status === 422;
}

// GitHub asking to slow down: Retry-After or an exhausted rate limit, 429, or its "rate limit"
// messages (a secondary rate limit can come as a 403 without a header)
function isRateLimit(e) {
  return e.retryAfter > 0 || e.status === 429 || /rate limit/i.test(e.message || "");
}

function backupRetryDelay(env, tries, retryAfter) {
  const base = backupRetrySeconds(env);
  const delay = Math.min(base * 2 ** (tries || 0), BACKUP_MAX_DELAY);
  return Math.ceil(Math.min(Math.max(delay, retryAfter || 0), 24 * 3600));
}

// ===== src/worker/backup/status.js ============================================================================

// How backups go, for the admin wiki (design 1.7): backups GitHub keeps refusing (not a rate limit:
// that only delays them) are recorded in _backup/status.json, one entry per tiddler: since (when its
// oldest waiting version was saved), last (its latest attempt), error (GitHub's answer) and status
// (its HTTP status, 0 without one). The entry goes when that tiddler's backup gets through. The file
// also keeps a pause of every backup, { until, count }, while there's one (queue.js), the last
// full backup (sync.js, queue.js): { id, startedAt, updatedAt, total, phase, steps, done, committed,
// removed, failed, finished }, and a note per big version being backed up (running: title ->
// { revision, size, started, attempt, sync }), written before the heavy part of a version over
// BIG_BACKUP_BYTES and cleared once the run is done with it: a run the runtime cuts short (the
// free plan's CPU time, on a version of several MB) runs nothing after the cut, the queue delivers
// it again three times the same way, then drops it, and the note is all that says why (design 1.7,
// 2.11). Written only when something changes, read only by a batch with a failure, a version that
// failed or waited before, or a big one, and by each step of a full backup. The admin wiki
// (src/browser/backup-alert.js) asks with its tiddler list request (X-Backup-Status: ask) when it
// loads, then hourly, at each request while an alert shows or a full backup runs, and shows an
// alert, and the full backup's progress in its control panel.


// An entry not retried for a day belongs to a backup no longer waiting (one still waiting is retried
// at least every 6 hours: BACKUP_MAX_DELAY), and is dropped
const BACKUP_STATUS_STALE = 24 * 3600 * 1000;

// The queue's retry limit, which the worker can't read: Cloudflare's default (setup 2.3: leave it)
const QUEUE_RETRIES = 3;

// A version this big gets a note before its backup's heavy part (queue.js, backupJob)
const BIG_BACKUP_BYTES = 1024 * 1024;
// A note whose run was cut short: its last delivery (the queue's retries used up), or one left
// this long (a backup takes seconds; the queue's retries follow within minutes)
const RUNNING_STALE_MS = 15 * 60 * 1000;

function backupFailure(job, e) {
  return { title: job.title, since: job.time || Date.now(), error: String(e.detail || e.message || e).slice(0, 200), status: e.status || 0 };
}

// { failing: title -> entry, pause, sync, running: title -> note }. strict: an R2 error throws,
// rather than reading as no file (a file that isn't JSON still reads as none)
async function readBackupStatus(env, strict) {
  let data = null;
  try {
    const obj = await env.WIKI_BUCKET.get(BACKUP_STATUS_KEY);
    try {
      data = obj ? await obj.json() : null;
    } catch {}
  } catch (e) {
    if (strict) throw e;
  }
  const failing = data && typeof data.failing === "object" && data.failing ? Object.entries(data.failing) : [];
  const pause = data && data.pause && data.pause.until > 0 ? { until: data.pause.until, count: data.pause.count || 0 } : null;
  const sync = data && data.sync && typeof data.sync === "object" && typeof data.sync.id === "string" ? data.sync : null;
  const running = data && typeof data.running === "object" && data.running ? Object.entries(data.running).filter(([, n]) => n && typeof n === "object") : [];
  return { failing: new Map(failing), pause, sync, running: new Map(running) };
}

// Notes a big version's backup as under way, before its heavy part. Never throws: a note that can't
// be written mustn't fail the backup it's about
async function noteRunning(env, note) {
  try {
    const status = await readBackupStatus(env, true);
    status.running.set(note.title, { revision: note.revision, size: note.size, started: note.started, attempt: note.attempt, ...(note.sync ? { sync: note.sync } : {}) });
    await writeBackupStatus(env, status);
  } catch (e) {
    console.error("[Backup] Could not note a big backup as under way:", e.message);
  }
}

// A full backup still going: started, not finished, and its last step not so long ago that it must
// have been lost (a message the queue dropped, say: a step takes seconds, pauses at most 6 hours)
const SYNC_STALE_MS = 8 * 3600 * 1000;

function syncRunning(sync) {
  return !!sync && !sync.finished && Date.now() - (sync.updatedAt || sync.startedAt || 0) < SYNC_STALE_MS;
}

// Records the full backup's state: patch merged into the stored one (or replacing it, if its id is
// another), with updatedAt now. stored: the status, if read already. Throws on an R2 error: a step
// that can't record its progress is retried (queue.js), the trigger answers 500.
async function recordSync(env, patch, stored) {
  const status = stored || await readBackupStatus(env, true);
  const sync = status.sync && status.sync.id === patch.id ? { ...status.sync, ...patch } : { ...patch };
  sync.updatedAt = Date.now();
  await writeBackupStatus(env, { ...status, sync });
  return sync;
}

// failures: from backupFailure; cleared: titles whose backup got through; pause: { until, count } of
// a pause that starts, null when one is over, undefined when that's not known; stored: the status
// file, if this run has read it already; finished: titles noted as under way (noteRunning) that this
// run is done with, however it went. Never throws: an R2 error here mustn't count as a failed backup
async function recordBackupResults(env, failures, cleared, pause, stored, finished = []) {
  try {
    await updateBackupStatus(env, failures, cleared, pause, stored, finished);
  } catch (e) {
    console.error("[Backup] Could not record how backups go:", e.message);
  }
}

async function updateBackupStatus(env, failures, cleared, pause, stored, finished) {
  const status = stored || await readBackupStatus(env, true), now = Date.now();
  const { failing, pause: storedPause, running } = status;
  let changed = false;
  for (const title of finished) changed = running.delete(title) || changed;
  for (const [title, note] of running) {
    // (A note left for a day belongs to a version no longer in the queue; also one with no time to go by)
    if (!(now - note.started <= BACKUP_STATUS_STALE)) changed = running.delete(title) || changed;
  }
  let keptPause = pause === undefined ? storedPause : pause;
  // (A pause over for a while no longer counts: gone)
  if (keptPause && now - keptPause.until >= PAUSE_CONTINUES) keptPause = null;
  if (JSON.stringify(keptPause) !== JSON.stringify(storedPause)) changed = true;
  for (const title of cleared) changed = failing.delete(title) || changed;
  for (const { title, since, error, status } of failures) {
    const entry = failing.get(title);
    failing.set(title, { since: entry ? Math.min(entry.since, since) : since, last: now, error, status });
    changed = true;
  }
  for (const [title, entry] of failing) {
    // (Also an entry that isn't one: no time to go by)
    if (!(now - entry.last <= BACKUP_STATUS_STALE)) changed = failing.delete(title) || changed;
  }
  if (!changed) return;
  await writeBackupStatus(env, { failing, pause: keptPause, sync: status.sync, running });
}

// The file as stored, or deleted when there's nothing to keep
async function writeBackupStatus(env, { failing, pause, sync, running }) {
  if (failing.size || pause || sync || (running && running.size)) {
    const status = { failing: Object.fromEntries(failing), ...(pause ? { pause } : {}), ...(sync ? { sync } : {}), ...(running && running.size ? { running: Object.fromEntries(running) } : {}) };
    await env.WIKI_BUCKET.put(BACKUP_STATUS_KEY, JSON.stringify(status), { httpMetadata: { contentType: "application/json" } });
  } else {
    await env.WIKI_BUCKET.delete(BACKUP_STATUS_KEY);
  }
}

// What the admin wiki is told: "off" (no backups: GITHUB_REPO or GITHUB_TOKEN missing), "ok", or
// encoded JSON with what there is to say: the backups failing for at least BACKUP_ALERT_MINUTES (60
// by default), as { count, title, since, error, status } of the oldest; a backup cut short (a note
// left behind by its last delivery, or for RUNNING_STALE_MS), as stuck: { count, title, size,
// attempts, started } of the oldest; the last full backup, as sync (running or finished); and
// backups: "off" when both apply to a worker without them
function backupReport(env, { failing, sync, running }) {
  const after = backupAlertMinutes(env) * 60000;
  const now = Date.now();
  const due = [...failing].filter(([, e]) => now - e.last <= BACKUP_STATUS_STALE && now - e.since >= after).sort((a, b) => a[1].since - b[1].since);
  const cut = [...(running || [])].filter(([, n]) => now - n.started <= BACKUP_STATUS_STALE && (n.attempt > QUEUE_RETRIES || now - n.started >= RUNNING_STALE_MS)).sort((a, b) => a[1].started - b[1].started);
  const on = !!github(env);
  if (!due.length && !cut.length && !sync) return on ? "ok" : "off";
  const report = {};
  if (due.length) {
    const [title, e] = due[0];
    Object.assign(report, { count: due.length, title: title.slice(0, 200), since: e.since, error: e.error, status: e.status });
  }
  if (cut.length) {
    const [title, n] = cut[0];
    report.stuck = { count: cut.length, title: title.slice(0, 200), size: n.size, attempts: n.attempt, started: n.started };
  }
  if (sync) report.sync = { ...sync, running: syncRunning(sync) };
  if (!on) report.backups = "off";
  return encodeURIComponent(JSON.stringify(report));
}

// A pause of every backup: GitHub asked to slow down, or refuses every backup (a token it no longer
// accepts, say), so trying them one by one would only make more calls (each answered the same way)
// and more queue operations. While it lasts, the backups delivered are sent again to wait for its
// end, without calling GitHub; then the first one tries. If GitHub still refuses, the next pause is
// twice as long (up to BACKUP_MAX_DELAY, or as long as GitHub asks).
// A failure within this time after a pause ended: the next pause is twice as long
const PAUSE_CONTINUES = 3600 * 1000;

// The next pause of every backup, after a failure e: { until (ms), count (pauses in a row, from 0),
// error (GitHub's, from the call that started it), all (GitHub refuses every backup, not just asking
// to wait: the ones waiting are recorded as failing, for the alert) }. last: the pause before, if any.
// The consumer keeps the pause for the later runs in its isolate (queue.js); until and count are
// also kept in the status file, for a run in a new one.
function nextPause(env, last, e) {
  const now = Date.now();
  // Still paused (a run that only knew from the status file): the same pause, for at least as long
  // as GitHub asks; just after one: twice as long; otherwise a first one
  const still = last && now < last.until;
  const count = !last ? 0 : still ? last.count : now - last.until < PAUSE_CONTINUES ? last.count + 1 : 0;
  const until = Math.max(now + backupRetryDelay(env, count, e.retryAfter) * 1000, still ? last.until : 0);
  return { until, count, error: e, all: !isRateLimit(e) };
}

// ===== src/worker/backup/queue.js =============================================================================

// The GitHub backup through a Cloudflare Queue (design 1.7): every save or delete becomes one
// message. The queue consumer (processBackupBatch, configured with max_concurrency 1) commits them
// one at a time, in order, one commit per save, so commits never collide, and GitHub rate limits or
// outages only delay backups: failed messages are put back with a growing delay until they go
// through. A rate limit or a token GitHub refuses pauses every backup; any other failure holds up
// only that tiddler's versions, so a file GitHub refuses can't hold up the others. Nothing runs
// while the queue is empty. Without a BACKUP_QUEUE binding (or if the queue is unavailable) the
// same backup runs directly.
// A full backup (started from the admin wiki, sync.js) runs here too, as a job that walks the stored
// tiddlers a step at a time and queues its next step (syncStep): GitHub ends up mirroring the bucket.


// A queue message, as sent: a version that would make it bigger waits in R2. (The queue takes up to
// 128 KB, but counts an operation per 64 KB of message: over 64 KB, a backup would cost 6 instead of 3.)
const QUEUE_MESSAGE_LIMIT = 64000;

const BACKUP_PER_RUN = 10;

// After this many bytes of versions, the rest of a run goes on to the next one: a megabyte takes a
// couple of milliseconds of CPU (its git hash, its base64, its copy), and a run gets about 10 on the
// free plan. A run always backs up one version, whatever its size.
const BACKUP_BYTES_PER_RUN = 512 * 1024;

// About the size of a message as the queue measures it: V8-serialized, where a string takes one
// byte a character if they're all Latin-1, two otherwise (so a text of 40 KB can be over 64 KB), with
// room for the other fields
function queueMessageSize(message) {
  let size = 200;
  for (const value of [message.title, message.content]) {
    if (typeof value === "string") size += value.length * (/[^\x00-\xff]/.test(value) ? 2 : 1);
  }
  return size;
}

// Called after a save or delete has been stored; job.content is the stored bytes
async function queueBackup(env, job) {
  if (!github(env)) return;
  const message = { action: job.action, title: job.title, revision: job.revision ?? null, time: Date.now(), tries: 0 };
  if (env.BACKUP_QUEUE) {
    try {
      if (job.action === "save") {
        // (Decoded only if it may fit: a character is at least one byte of UTF-8)
        const content = job.content.length < QUEUE_MESSAGE_LIMIT ? decoder.decode(job.content) : null;
        if (content !== null && queueMessageSize({ ...message, content }) <= QUEUE_MESSAGE_LIMIT) {
          message.content = content;
        } else {
          // Keep this exact version until it is committed (R2 itself only holds the latest one).
          // Not named after the title, which can be too long for a key (or guessed: the copy is public)
          message.contentKey = `_backup/versions/${message.time}-${crypto.randomUUID()}.json`;
          await env.WIKI_BUCKET.put(message.contentKey, job.content, { httpMetadata: { contentType: "application/json" } });
        }
      }
      await env.BACKUP_QUEUE.send(message);
      return;
    } catch (e) {
      console.error(`[Backup] Could not queue '${job.title}', backing up directly:`, e.message);
      if (message.contentKey) await env.WIKI_BUCKET.delete(message.contentKey).catch(() => {});
    }
  }
  // No queue: run the same backup right away, with a couple of quick retries
  const direct = { ...message, content: job.content, contentKey: undefined };
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      await backupJob(env, direct);
      return await recordBackupResults(env, [], [job.title]);
    } catch (e) {
      if (attempt < 3) {
        await new Promise(resolve => setTimeout(resolve, waitMs(env, 1000 * attempt)));
        continue;
      }
      console.error(`[Backup] '${job.title}' could not be backed up:`, e.message);
      await recordBackupResults(env, [backupFailure(direct, e)], []);
    }
  }
}

// The pause of every backup, if one is on (nextPause in status.js), kept for the later runs in this isolate
let backupPause = null;

// The titles recorded as failing in the status file (status.js), as this instance knows them: read
// once, at its first backup that goes through (the file is otherwise read only by a run with a
// failure, a retry or a pause), then kept up to date with what it records and clears. null until
// then. A backup of such a title that goes through clears its entry whatever its own history: a
// fresh save of a tiddler a full backup found refused, fixed since, say.
let failingTitles = null;

async function recordedAsFailing(env, title) {
  if (failingTitles === null) {
    try {
      failingTitles = new Set((await readBackupStatus(env, true)).failing.keys());
    } catch {
      return false;   // not known this time: the next backup that goes through asks again
    }
  }
  return failingTitles.has(title);
}

function noteFailing(failures) {
  if (failingTitles) for (const failure of failures) failingTitles.add(failure.title);
}

// Queue consumer
async function processBackupBatch(batch, env) {
  const messages = [...batch.messages].sort((a, b) =>
    (a.body.time - b.body.time) || String(a.body.revision).localeCompare(String(b.body.revision)));
  const held = new Map();   // title -> delay: a version of it failed, its later versions wait with it
  const failures = [], cleared = [], finished = [];   // for the backup status (backupFailure; finished: big versions noted, done with)
  let pause;                // for the status file: a pause that starts in this run, or null if one is over
  let stored;               // the status file, if read in this run
  let denied;               // a tiddler GitHub answered 403 or 404 in this run (see isAccountWide)
  let attempts = 0;
  const work = { bytes: 0, calls: 0 };   // the size of the versions handled so far (BACKUP_BYTES_PER_RUN), the GitHub calls made
  const syncSteps = [];        // a full backup's step, run after the saves with what's left of the run's calls
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    if (backupPause && Date.now() < backupPause.until) {
      // Waits for the pause to end. (Marked, so that its backup going through ends the pause in the
      // status file too)
      await requeueBackup(env, msg, Math.ceil((backupPause.until - Date.now()) / 1000), false, { paused: true });
      if (backupPause.all && msg.body.action !== "sync") failures.push(backupFailure(msg.body, backupPause.error));
      continue;
    }
    if (msg.body.action === "sync") {
      syncSteps.push(msg);
      continue;
    }
    if (held.has(msg.body.title)) {
      await requeueBackup(env, msg, held.get(msg.body.title), false);
      continue;
    }
    if (attempts >= BACKUP_PER_RUN || work.bytes >= BACKUP_BYTES_PER_RUN) {
      await requeueBackup(env, msg, 0, false);
      continue;
    }
    attempts++;
    const delivery = { attempt: msg.attempts };   // (noted: a big version, noted as under way)
    try {
      await backupJob(env, msg.body, work, delivery);
      msg.ack();
      backupPause = null;   // GitHub takes backups (again)
      // (The backup is done: a copy that can't be removed is only left behind)
      if (msg.body.contentKey) await env.WIKI_BUCKET.delete(msg.body.contentKey).catch(() => {});
      // A version that failed or waited before clears a recorded failure, and a recorded pause; so
      // does any version of a title recorded as failing (recordedAsFailing)
      const waited = msg.body.tries > 0 || msg.body.paused || msg.attempts > 1;
      if (waited || await recordedAsFailing(env, msg.body.title)) {
        cleared.push(msg.body.title);
        if (failingTitles) failingTitles.delete(msg.body.title);
        if (waited) pause = null;
      }
    } catch (e) {
      if (delivery.noted) finished.push(msg.body.title);
      if (isRateLimit(e) || e.status === 401 || (isAccountWide(e) && denied !== undefined && denied !== msg.body.title)) {
        // Every backup waits: this one, the rest of this run (above), and the next runs. (A rate
        // limit isn't a failure to report: a big import waits like this for hours.)
        let last = backupPause;
        if (!last) {
          try {
            stored = await readBackupStatus(env, true);
            last = stored.pause;
          } catch {}
        }
        backupPause = nextPause(env, last, e);
        pause = { until: backupPause.until, count: backupPause.count };
        const delay = Math.ceil((backupPause.until - Date.now()) / 1000);
        console.error(`[Backup] Backups paused for ${delay}s: ${e.message}`);
        await requeueBackup(env, msg, delay, true);
        if (backupPause.all) failures.push(backupFailure(msg.body, e));
        continue;
      }
      if (isAccountWide(e)) denied = msg.body.title;
      const delay = backupRetryDelay(env, msg.body.tries, e.retryAfter);
      console.error(`[Backup] '${msg.body.title}' not backed up yet (${e.message}); retrying in ${delay}s`);
      await requeueBackup(env, msg, delay, true, isRefusal(e) ? { refused: true } : undefined);
      // Anything else may concern this file only, and other tiddlers' backups go ahead. Its later
      // versions wait with it, so they stay in order, unless GitHub refuses this version for good
      // (its path, or a secret in its text): the next one may be fine, and goes ahead (the late
      // versions logic keeps GitHub on the newest)
      if (!isRefusal(e)) held.set(msg.body.title, delay);
      failures.push(backupFailure(msg.body, e));
      continue;
    }
    if (delivery.noted) finished.push(msg.body.title);
  }
  // A full backup's step: one a run, with the calls the saves left (a step itself records what it did)
  let stepRun = false;
  for (const msg of syncSteps) {
    const budget = GITHUB_CALLS_PER_RUN - work.calls;
    if (stepRun || budget < SYNC_MIN_CALLS || (backupPause && Date.now() < backupPause.until)) {
      await requeueBackup(env, msg, backupPause && Date.now() < backupPause.until ? Math.ceil((backupPause.until - Date.now()) / 1000) : 0, false);
      continue;
    }
    stepRun = true;
    try {
      const next = await syncStep(env, msg.body, work, budget, { attempt: msg.attempts, sync: msg.body.id });
      msg.ack();
      backupPause = null;
      if (next) await env.BACKUP_QUEUE.send(next);
    } catch (e) {
      if (isRateLimit(e) || isAccountWide(e)) {
        // Every backup waits (as above)
        let last = backupPause;
        if (!last) {
          try {
            stored = await readBackupStatus(env, true);
            last = stored.pause;
          } catch {}
        }
        backupPause = nextPause(env, last, e);
        pause = { until: backupPause.until, count: backupPause.count };
        const delay = Math.ceil((backupPause.until - Date.now()) / 1000);
        console.error(`[Backup] Backups paused for ${delay}s (full backup, step ${msg.body.steps || 0}): ${e.message}`);
        await requeueBackup(env, msg, delay, true);
        continue;
      }
      const delay = backupRetryDelay(env, msg.body.tries, e.retryAfter);
      console.error(`[Backup] Full backup step not done (${e.message}); trying again in ${delay}s`);
      await requeueBackup(env, msg, delay, true);
    }
  }
  noteFailing(failures);
  if (failures.length || cleared.length || finished.length || pause !== undefined) await recordBackupResults(env, failures, cleared, pause, stored, finished);
}

// --- A full backup (design 1.7): GitHub made to mirror the bucket -----------------------------------
// Started from the admin wiki (POST /backup/sync, sync.js), for tiddlers that predate the backup, a
// restore, a tiddler put in R2 by hand, or any doubt. A message carries where it stands: { action:
// "sync", id, startedAt, phase, after, pending, total, done, committed, removed, failed, steps, time, tries }.
// The push phase walks the stored tiddlers in key order (after: the last key walked), each through the
// same backup as a save (backupJob): nothing is committed for one GitHub has the same bytes of, and a
// file GitHub refuses is reported like a save's would be, the walk going on. Then the prune phase lists
// GitHub's tiddler files in one call (the tree) and removes those whose titles are no longer stored
// (pending: the ones left to remove). Each step stays within a run's budgets: the GitHub calls the
// saves of the same run left (GITHUB_CALLS_PER_RUN), the bytes (BACKUP_BYTES_PER_RUN); a step records
// what it did in the status file (recordSync) and queues the next, so a wiki of any size goes through
// in as many steps as it takes, at 3 queue operations a step. Idempotent: run again, it commits nothing.

// Of the 50 calls a run may make outside Cloudflare; a save's backup takes up to 3
const GITHUB_CALLS_PER_RUN = 40;

// A step starts only with this many calls left in the run (one tiddler takes up to 3)
const SYNC_MIN_CALLS = 8;

const SYNC_LIST_LIMIT = 100;

// What a prune message carries of the files still to remove (titles and shas, as the queue would
// measure them): what fits with room to spare under a message's 64 KB, so a step stays 3 operations;
// more than that, and the tree is listed again once they're removed
const SYNC_PENDING_BYTES = 56 * 1024;

// One step. Returns the next step's message, or null once done. Throws on an error that stops the
// step (GitHub down, a rate limit, a refused token, R2): the step is retried, its progress recorded
// as an error meanwhile. A step of a full backup another one has replaced since (started again
// after this one's step was lost for hours) does nothing.
async function syncStep(env, body, work, budget, delivery) {
  const stored = await readBackupStatus(env, true);
  if (stored.sync && stored.sync.id !== body.id && stored.sync.startedAt > body.time) {
    console.log("[Backup] Sync step of a full backup replaced by a newer one: dropped");
    return null;
  }
  const github = githubContents(env, work);
  const callsAtStart = work.calls;
  const used = () => work.calls - callsAtStart;
  let { done = 0, committed = 0, removed = 0, failed = 0, steps = 0, total = null } = body;
  steps++;
  const failures = [], through = [], finished = [];   // what GitHub refused, the titles it took or already had, the big ones noted
  let next;
  try {
    next = await syncWork(env, github, body, work, budget, used, counts => ({ done, committed, removed, failed } = counts), failures, through, finished, delivery);
  } catch (e) {
    if (finished.length) await recordBackupResults(env, [], [], undefined, undefined, finished);
    await recordSync(env, { id: body.id, error: String(e.detail || e.message || e).slice(0, 200) }, stored).catch(() => {});
    throw e;
  }
  console.log(`[Backup] Sync step ${steps}: ${done}/${total ?? "?"} walked, ${committed} committed, ${removed} removed, ${failed} failed, ${used()} GitHub calls`);
  // A tiddler recorded as failing that this step committed, or found GitHub already has: cleared
  const cleared = through.filter(title => stored.failing.has(title));
  noteFailing(failures);
  if (failingTitles) for (const title of cleared) failingTitles.delete(title);
  if (failures.length || cleared.length || finished.length) await recordBackupResults(env, failures, cleared, undefined, undefined, finished);
  const startedAt = body.startedAt || body.time;
  await recordSync(env, { id: body.id, startedAt, total, phase: next ? next.phase : "prune", steps, done, committed, removed, failed, error: undefined, ...(next ? {} : { finished: Date.now() }) });
  return next ? { action: "sync", id: body.id, startedAt, total, done, committed, removed, failed, steps, time: Date.now(), tries: 0, ...next } : null;
}

// The step's work: the next slice of the push, or of the prune. report(counts) hands back the counts
// as they stand (also when an error stops the step partway); through gets the titles GitHub took or
// already had; finished the big ones noted as under way (noteBigVersion) and done with; delivery:
// the step's message's attempt and the full backup's id, for the notes. Returns what the next step
// is, or null.
async function syncWork(env, github, body, work, budget, used, report, failures, through, finished, delivery) {
  let { done = 0, committed = 0, removed = 0, failed = 0 } = body;
  const counts = () => report({ done, committed, removed, failed });
  if (body.phase === "push") {
    let after = body.after || null, stopped = false;
    for (;;) {
      const listing = await env.WIKI_BUCKET.list({ prefix: TIDDLER_PREFIX, limit: SYNC_LIST_LIMIT, include: ["customMetadata"], ...(after ? { startAfter: after } : {}) });
      for (const item of listing.objects) {
        if (used() + 3 > budget || work.bytes >= BACKUP_BYTES_PER_RUN) {
          stopped = true;
          break;
        }
        const title = item.key.slice(TIDDLER_PREFIX.length);
        // (What the list leaves out is left out here too: an object not in the stored layout)
        if (item.customMetadata?.layout === FLAT_LAYOUT && !isEphemeralTitle(title)) {
          const obj = await env.WIKI_BUCKET.get(item.key);
          if (obj) {
            const job = { action: "save", title, revision: revisionOf(obj), time: Date.now() };
            let noted = await noteBigVersion(env, job, obj.size, delivery);
            job.content = new Uint8Array(await obj.arrayBuffer());
            try {
              if (await backupJob(env, job, work) === "committed") committed++;
              through.push(title);
            } catch (e) {
              if (noted) {
                finished.push(title);   // (done with it, however it went: the note goes with the step's record)
                noted = false;
              }
              if (!isRefusal(e)) throw e;
              failed++;
              failures.push(backupFailure(job, e));
            }
            if (noted) finished.push(title);
          }
        }
        done++;
        after = item.key;
        counts();
      }
      if (stopped || !listing.truncated) break;
    }
    return stopped ? { phase: "push", after } : { phase: "prune" };
  }
  // The prune: GitHub's tiddler files (one call), the stored keys (one R2 call per 1,000), the difference
  let pending = body.pending;
  if (!pending) {
    const files = await github.tiddlerFiles();
    if (files === null) {
      console.error("[Backup] Full backup: GitHub's tree is too big to list in one call, so files of titles no longer in the wiki aren't removed");
      pending = [];
    } else {
      const titles = await storedTitles(env);
      pending = files.filter(file => !titles.has(file.title));
    }
  }
  while (pending.length && used() + 1 <= budget) {
    const file = pending.shift();
    try {
      await github.remove(file.title, file.sha, `🗑️ Full backup: ${file.title} is no longer in the wiki`);
      removed++;
      counts();
    } catch (e) {
      // Gone meanwhile (404), or changed meanwhile, a save that landed (409): left alone
      if (e.status !== 404 && e.status !== 409) throw e;
    }
  }
  if (pending.length) {
    // As many as fit the next message (a title takes two bytes a character past Latin-1, as a text does)
    const carried = [];
    let bytes = 0;
    for (const file of pending) {
      bytes += (file.title.length + file.sha.length + 32) * (/[^\x00-\xff]/.test(file.title) ? 2 : 1);
      if (bytes > SYNC_PENDING_BYTES && carried.length) break;
      carried.push(file);
    }
    // (more: files past this message, to find by listing the tree again once these are removed;
    // kept from the message before, where the list came from, until that listing)
    return { phase: "prune", pending: carried, ...(carried.length < pending.length || body.more ? { more: true } : {}) };
  }
  return body.more ? { phase: "prune" } : null;
}

// The titles of every stored tiddler (its key without the prefix), 1,000 a call
async function storedTitles(env) {
  const titles = new Set();
  let cursor;
  do {
    const listing = await env.WIKI_BUCKET.list({ prefix: TIDDLER_PREFIX, limit: 1000, ...(cursor ? { cursor } : {}) });
    for (const item of listing.objects) titles.add(item.key.slice(TIDDLER_PREFIX.length));
    cursor = listing.truncated ? listing.cursor : undefined;
  } while (cursor);
  return titles;
}

// How long the queue keeps a message from when it was sent: 24 hours on the free plan (the least)
const QUEUE_RETENTION = 24 * 3600 * 1000;

// Puts a message back, to be delivered again after delaySeconds. While it only waits (nothing in it
// changes but being marked paused, which its next delivery shows anyway: msg.attempts) and has a
// retry left, with a delivery to spare, before the queue would drop it, by its retry limit or its
// retention, the queue's own retry: 1 operation, the next delivery. Otherwise it's sent again as a
// fresh message, which neither limit applies to: 3 operations (sent, delivered, acknowledged).
// countTry: one more failed try; extra: fields to add to it
async function requeueBackup(env, msg, delaySeconds, countTry, extra) {
  const onlyWaits = !countTry && (!extra || (Object.keys(extra).length === 1 && extra.paused === true));
  const sent = msg.timestamp instanceof Date ? msg.timestamp.getTime() : NaN;
  if (onlyWaits && msg.attempts >= 1 && msg.attempts < QUEUE_RETRIES &&
      Date.now() + delaySeconds * 1000 < sent + QUEUE_RETENTION - 3600 * 1000) {
    msg.retry(delaySeconds > 0 ? { delaySeconds } : undefined);
    return;
  }
  const body = { ...msg.body, ...(countTry ? { tries: (msg.body.tries || 0) + 1 } : {}), ...extra };
  try {
    await env.BACKUP_QUEUE.send(body, delaySeconds > 0 ? { delaySeconds } : undefined);
    msg.ack();
  } catch (e) {
    msg.retry(delaySeconds > 0 ? { delaySeconds } : undefined);
  }
}

// A version over BIG_BACKUP_BYTES, about to be backed up from the queue (delivery: { attempt, sync }):
// noted in the status file as under way (status.js, noteRunning), before the heavy part — the bytes
// copied, hashed and encoded, which on the free plan can take a run past its CPU time, after which
// nothing runs, the queue delivers the message again the same way, three times, then drops it, and
// this note is all that says why. The run clears it once done with the version (finished). Not for
// a direct backup (no queue: the save's own request, which answers its error). Returns whether noted.
async function noteBigVersion(env, job, size, delivery) {
  if (!delivery || !(size > BIG_BACKUP_BYTES)) return false;
  await noteRunning(env, { title: job.title, revision: job.revision, size, started: Date.now(), attempt: delivery.attempt, sync: delivery.sync });
  delivery.noted = true;
  return true;
}

// Commits one save or delete. job.content: the version as text (in a queue message) or bytes (a
// direct backup). work.bytes: adds the size of the versions it handles; work.calls: the GitHub calls.
// delivery: from the queue, { attempt, sync } (noted set here when the version got a note, see
// noteBigVersion). Returns "committed" when it wrote GitHub's file, "same" when GitHub already had
// these bytes
async function backupJob(env, job, work = { bytes: 0, calls: 0 }, delivery = null) {
  const github = githubContents(env, work);
  const current = await env.WIKI_BUCKET.head(tiddlerKey(job.title));   // the version in the wiki now

  if (job.action === "delete") {
    if (current) return; // Recreated since then: its own save message updates GitHub
    const existing = await github.get(job.title);
    if (existing) await github.remove(job.title, existing.sha, `🗑️ Delete: ${job.title}`);
    return;
  }

  // (As bytes: what GitHub gets, and what its sha is computed from)
  let content = typeof job.content === "string" ? encoder.encode(job.content) : job.content;
  if (content === undefined && job.contentKey) {
    const stored = await env.WIKI_BUCKET.get(job.contentKey);
    if (stored) await noteBigVersion(env, job, stored.size, delivery);
    content = stored ? new Uint8Array(await stored.arrayBuffer()) : undefined;
  }
  if (content === undefined) return; // Already handled by an earlier delivery of this message
  work.bytes += content.length;

  // GitHub needs the sha of the file it holds to replace it. Its content isn't needed (decoding a
  // plugin's took more CPU than a run is allowed): whether GitHub already holds a newer version is
  // told by the sha too, compared with the wiki's current version's
  const existing = await github.get(job.title);
  let sha = existing ? existing.sha : null;
  const newer = await newerInWiki(env, job, current, sha, work);
  // A version GitHub refused for good, now replaced there by a newer one, or whose tiddler has been
  // deleted since: dropped, rather than tried forever (it would only have been history)
  if (job.refused && (newer || !current)) return;
  // (A retry after the restore below failed: this version is already in the history, even if a
  // newer one has been committed on top since)
  let outcome = "same";
  if (!job.restore && sha !== await gitBlobSha(content)) {
    sha = await github.put(job.title, content, `✏️ Save: ${job.title}`, sha);
    outcome = "committed";
  }
  if (newer) {
    // This version arrived after a newer one was committed: it is now in the history, and the
    // newer version goes back on top. (Marked first: if putting it back fails, the retry of this
    // message, which finds this version already committed, still does it.)
    job.restore = true;
    if (sha !== newer.sha) await github.put(job.title, newer.bytes, `✏️ Save: ${job.title} (newer version restored)`, sha);
  } else if (!current) {
    // Deleted since this save: keep this version in the history, then delete it again
    await github.remove(job.title, sha, `🗑️ Delete: ${job.title}`);
  }
  return outcome;
}

// The wiki's current version of a tiddler, { bytes, sha }, if it's newer than this job's and GitHub
// already holds it (githubSha), so this job's version arrived late; or if an earlier try of this
// job found that (job.restore). Otherwise null: a newer version still waiting for its own backup
// (quick successive edits) is committed by its own message, in order.
async function newerInWiki(env, job, current, githubSha, work) {
  if (!current || !isNewerRevision(revisionOf(current), job.revision) || (!githubSha && !job.restore)) return null;
  const obj = await env.WIKI_BUCKET.get(tiddlerKey(job.title));
  if (!obj) return null;
  const bytes = new Uint8Array(await obj.arrayBuffer());
  work.bytes += bytes.length;
  const sha = await gitBlobSha(bytes);
  return job.restore || sha === githubSha ? { bytes, sha } : null;
}

// ===== src/worker/http.js =====================================================================================

// The small shared pieces of answering a request: paths, ETags and preconditions (design 1.2),
// standard answers, and work that outlives the answer.
//
// Edit-conflict protection, in short:
//  * Every tiddler has a revision: customMetadata.revision, a millisecond timestamp set on each
//    save. GET returns it in the body and in the ETag "default/<title>/<revision>:auto".
//  * The conflict guard (src/browser/conflict-guard.js, built into the page) sends the revision its edit
//    is based on as If-Match, or If-None-Match: * for a brand new tiddler.
//  * PUT/DELETE answer 412 when that revision is no longer current (checkPreconditions), and the R2
//    write itself is conditional (saves.js), so two saves arriving at the same moment can't both win.
//  * Requests without If-Match/If-None-Match (old tabs, scripts) are accepted.

// A path, or the title in one, decoded; null if it isn't valid percent-encoding
function decodePath(text) {
  try {
    return decodeURIComponent(text);
  } catch {
    return null;
  }
}

function invalidPath(corsHeaders) {
  return new Response("Invalid path: it isn't valid percent-encoding", { status: 400, headers: corsHeaders });
}

function tiddlerEtag(title, revision) {
  return `"default/${encodeURIComponent(title)}/${revision}:auto"`;
}

// Turns an If-Match / If-None-Match header into revisions ("*" stays "*"). Accepts full TiddlyWeb
// ETags ("bag/title/revision:hash"), bare revisions, and weak (W/) or unquoted forms.
function parseEtagList(header) {
  if (!header) return [];
  return header.split(",")
    .map(token => token.trim().replace(/^W\//i, "").replace(/^"(.*)"$/, "$1").trim())
    .map(token => {
      if (token === "*") return token;
      const slash = token.lastIndexOf("/");
      const colon = token.lastIndexOf(":");
      return colon > slash ? token.substring(slash + 1, colon) : token.substring(slash + 1);
    })
    .filter(revision => revision && revision !== "undefined" && revision !== "null");
}

// Evaluates If-Match / If-None-Match against the current revision (null if the tiddler doesn't exist)
function checkPreconditions(request, currentRevision) {
  const ifMatch = parseEtagList(request.headers.get("If-Match"));
  const ifNoneMatch = parseEtagList(request.headers.get("If-None-Match"));
  let reason = null;
  if (ifMatch.length > 0) {
    if (currentRevision === null) reason = "it was deleted in another tab or browser";
    else if (!ifMatch.includes("*") && !ifMatch.includes(currentRevision)) reason = "it was changed in another tab or browser";
  }
  if (!reason && ifNoneMatch.length > 0 && currentRevision !== null &&
      (ifNoneMatch.includes("*") || ifNoneMatch.includes(currentRevision))) {
    reason = "a tiddler with this title was created in another tab or browser";
  }
  return { conditional: ifMatch.length > 0 || ifNoneMatch.length > 0, reason };
}

// Response headers for an R2 object: its stored HTTP metadata plus CORS
function objectHeaders(object, corsHeaders) {
  const headers = new Headers(corsHeaders);
  object.writeHttpMetadata(headers);
  return headers;
}

function conflictResponse(title, reason, currentRevision, corsHeaders) {
  const headers = { ...corsHeaders, "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" };
  if (currentRevision !== null) headers.ETag = tiddlerEtag(title, currentRevision);
  return new Response(`Edit conflict: '${title}' was not saved because ${reason}.`, { status: 412, headers });
}

// The answer to a save: TiddlyWiki reads the new revision from the ETag
function savedResponse(title, revision, corsHeaders) {
  return new Response(null, { status: 204, headers: { ...corsHeaders, ETag: tiddlerEtag(title, revision) } });
}

function refusal(message, corsHeaders, status = 400) {
  return new Response(message, { status, headers: { ...corsHeaders, "Content-Type": "text/plain; charset=utf-8" } });
}

// Waits for work the response depends on, and keeps it running even if the browser disconnects
// first (a reload while the page is being rebuilt, say): without waitUntil it could be cancelled
function untilDone(ctx, promise) {
  ctx.waitUntil(promise.catch(() => {}));
  return promise;
}

// ===== src/worker/cache.js ====================================================================================

// The public site's cache: the public wiki is served straight from the R2 bucket through
// Cloudflare's cache, so after a change the worker purges exactly the public URLs that serve it
// (single-file purge, not purge_everything; design 1.6). A private wiki has no public site, so
// nothing to purge.


// The query string is part of the cache key, so the tiddler list is purged under each URL
// TiddlyWiki requests it with: the TiddlyWiki 5.4 filter, the filter of earlier versions, and bare.
const SKINNY_LIST_FILTERS = [
  "[all[tiddlers]] -[[$:/isEncrypted]] -[prefix[$:/temp/]] -[prefix[$:/status/]] -[[$:/boot/boot.js]] -[[$:/boot/bootprefix.js]] -[has[plugin-type]field:platform[server]] -[[$:/library/sjcl.js]] -[[$:/core]]",
  "[all[tiddlers]] -[[$:/isEncrypted]] -[prefix[$:/temp/]] -[prefix[$:/status/]] -[[$:/boot/boot.js]] -[[$:/boot/bootprefix.js]] -[[$:/library/sjcl.js]] -[[$:/core]]"
];

// URLs that serve the wiki page itself
const PUBLIC_PAGE_PATHS = ["/", "/baked.html"];

// Encoded the same way TiddlyWiki encodes them when it requests them. The admin page reads tiddlers
// from the public site too, cross-origin: its requests carry an Origin header, which Cloudflare
// keeps in the cache key, so its copy is a separate cache entry, purged with that header.
function tiddlerPurgeUrls(env, title, adminOrigin) {
  const url = publicUrl(env, `/recipes/default/tiddlers/${encodeURIComponent(title)}`);
  return [url, { url, headers: { Origin: adminOrigin } }, ...listPurgeUrls(env)];
}

function listPurgeUrls(env) {
  return [
    publicUrl(env, "/recipes/default/tiddlers.json"),
    ...SKINNY_LIST_FILTERS.map(filter => publicUrl(env, `/recipes/default/tiddlers.json?filter=${encodeURIComponent(filter)}`))
  ];
}

async function purgePublicCache(env, urls) {
  const zone = purges(env);
  if (!zone || !publicSite(env) || urls.length === 0) return;
  try {
    const res = await fetch(`https://api.cloudflare.com/client/v4/zones/${zone.zoneId}/purge_cache`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${zone.token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ files: urls })
    });
    if (!res.ok) console.error(`Cache purge failed (${res.status}):`, await res.text());
  } catch (e) {
    console.error("Cache purge exception:", e.message);
  }
}

// ===== src/worker/list.js =====================================================================================

// The tiddler list (recipes/default/tiddlers.json, design 1.2): what TiddlyWiki loads at boot, one
// entry per stored tiddler with every field but the text. Changed with conditional writes, so two
// saves can't lose each other's entry, and rebuilt from the stored tiddlers when missing or damaged.
//
// The list is an index: every tiddler is also stored on its own, with all its fields. If the list
// is missing or damaged (a bad upload or hand edit), the worker rebuilds it from the stored
// tiddlers wherever it needs it (serving it, a save, a delete, a page build) and carries on. The
// damaged copy is kept in _repair/. Nothing runs in the background: the requests do the work.
//
// A request may make 1,000 R2 calls and use about 10 ms of CPU (Free plan), so a big wiki is
// rebuilt a step per request, its progress kept in _repair/. Until the last step the damaged list
// stays as it is, and the list, saves and deletes answer 503 without changing anything, so the
// browser simply asks again: the conflict guard at once, TiddlyWiki itself every 5 seconds.


// Drops anything that should never have been listed (drafts, story list, state...)
function scrubList(list) {
  return list.filter(t => !isEphemeralTitle(t.title || "") && !isDraft(t));
}

// The list's entries, or null if it isn't a JSON array of tiddlers
function parseList(text) {
  try {
    const entries = JSON.parse(text);
    return Array.isArray(entries) && entries.every(e => e !== null && typeof e === "object" && typeof e.title === "string") ? entries : null;
  } catch (e) {
    return null;
  }
}

// The list as stored: entries is null if it's missing (object null) or damaged
async function getList(env) {
  const object = await env.WIKI_BUCKET.get(LIST_KEY);
  if (!object) return { object: null, text: null, entries: null };
  const text = await object.text();
  return { object, text, entries: parseList(text) };
}

// The revision a list (readableList) has for a title, or null if it isn't listed
function listedRevision(list, title) {
  const entry = list.entries.find(e => e.title === title);
  return entry && entry.revision !== undefined && entry.revision !== null ? String(entry.revision) : null;
}

// The list, readable: { object, text, entries }. A missing or damaged list is rebuilt from the
// stored tiddlers first; throws ListRebuilding while that takes more requests.
async function readableList(env, ctx, options) {
  const list = await getList(env);
  if (list.entries) return list;
  const rebuilt = await rebuildList(env, ctx, list, options);
  const entries = rebuilt?.entries;   // parsed once
  if (!entries) throw new ListRebuilding();
  return { object: rebuilt.object, text: rebuilt.text, entries };
}

// mutator(entries, attempt) returns the new list, or null when nothing needs to change (it may look
// something up first: a retried attempt means another request changed the list meanwhile). list: the
// list already read (readableList), used for the first attempt. Returns the list as now stored,
// { object, text, entries }, so a page build right after needn't read it again.
async function changeList(env, ctx, mutator, list = null, attempts = 5) {
  for (let attempt = 1; attempt <= attempts; attempt++) {
    const { object: existing, text: existingText, entries } = list || await readableList(env, ctx);
    list = null;
    const etag = existing.etag || existing.httpEtag.replace(/"/g, "");

    const current = scrubList(entries);
    const changed = await mutator(current, attempt);
    if (changed === null) return { object: existing, text: existingText, entries: current };

    // Only if the list is still the one we read
    const text = JSON.stringify(changed);   // compact: a third smaller than indented, cheaper to write and read
    const written = await env.WIKI_BUCKET.put(LIST_KEY, text, {
      httpMetadata: { contentType: "application/json" },
      onlyIf: { etagMatches: etag }
    });

    if (written !== null) return { object: written, text, entries: changed };

    console.warn(`[Tiddler list] Write conflict detected, retrying (${attempt}/${attempts})...`);
    // A short, growing, slightly random pause, so saves that collided don't collide again
    await new Promise(resolve => setTimeout(resolve, 25 * attempt + Math.random() * 25));
  }

  throw new Error(`The tiddler list couldn't be updated: ${attempts} saves in a row got to it first. Try again.`);
}

// A tiddler's entry in the list: every field but the text. title: the title it's stored under
// (always text, whatever the body says); fields: the tiddler without its text.
// date fills in a missing modified or created date.
function listEntry(title, fields, revision, date = getTwTimestamp()) {
  const rest = { ...fields };
  delete rest.text;
  delete rest.revision;
  delete rest.bag;
  delete rest.recipe;
  return {
    ...rest,
    title,
    bag: "default",
    recipe: "default",
    modified: fields.modified || date,
    created: fields.created || date,
    tags: fields.tags || [],
    type: fields.type || "text/vnd.tiddlywiki",
    revision: String(revision),
    _is_skinny: ""
  };
}

// Returns { previous: the entry it replaced, or null; list: the list as now stored; superseded: a
// newer save of the tiddler is already listed (this save's list write was retried after it), so the
// list keeps that one; gone: the tiddler is no longer stored at this revision (a delete, or a
// recreate, landed while this save's list write was retried), so it isn't listed }
async function updateList(env, ctx, title, fields, revision, list = null) {
  const entry = listEntry(title, fields, revision);
  let previous = null, superseded = false, gone = false;
  const stored = await changeList(env, ctx, async (entries, attempt) => {
    const idx = entries.findIndex(t => t.title === title);
    previous = idx >= 0 ? entries[idx] : null;
    superseded = !!previous && isNewerRevision(String(previous.revision), revision);
    if (superseded) return null;
    if (idx < 0) {
      // Unlisted on a retried attempt: a delete may have landed meanwhile (its list write is what
      // made this one fail) and removed the object with it, R2 deletes being unconditional. Only
      // what's stored is listed, and a version recreated since is listed by its own save
      if (attempt > 1) {
        const object = await env.WIKI_BUCKET.head(tiddlerKey(title));
        gone = !object || revisionOf(object) !== String(revision);
        if (gone) return null;
      }
      entries.push(entry);
      return entries;
    }
    entries[idx] = entry;
    // Listed twice (a hand edit, say): listed once from now on
    return entries.some((t, i) => i > idx && t.title === title) ? entries.filter((t, i) => i <= idx || t.title !== title) : entries;
  }, list);
  return { previous, list: stored, superseded, gone };
}

// Returns { removed: the entry it removed, or null if the title wasn't listed; list: the list as now
// stored; recreated: the title was saved again since the deleted revision (this delete's list write
// was retried after that save), so its entry stays }
async function removeFromList(env, ctx, title, list = null, deletedRevision = null) {
  let removed = null, recreated = false;
  const stored = await changeList(env, ctx, (entries) => {
    removed = entries.find(t => t.title === title) || null;
    recreated = !!removed && !!deletedRevision && isNewerRevision(String(removed.revision), deletedRevision);
    if (recreated) removed = null;
    return removed ? entries.filter(t => t.title !== title) : null;
  }, list);
  return { removed, list: stored, recreated };
}

const REPAIR_STEP_TIDDLERS = 100;

const REPAIR_STALE_MS = 2 * 60 * 1000;

const LIST_REBUILDING = "The tiddler list is being rebuilt from the stored tiddlers. Try again in a moment.";

// Stands in for a missing list during a rebuild, so that each rebuild has its own list to replace
// (hence the time and random part). Public tabs read it straight from R2, so it isn't JSON:
// TiddlyWiki would take any JSON for a list and remove every tiddler not in it. The conflict guard
// recognises the first words and asks again a little later (it has the same text: keep both in step).
const LIST_STAND_IN_MARK = "Tiddler list being rebuilt";

function listStandIn() {
  return `${LIST_STAND_IN_MARK} (${new Date().toISOString()} ${crypto.randomUUID()})\n` +
    "The list was missing: the worker is rebuilding it from the stored tiddlers.\n";
}

function isListStandIn(text) {
  return typeof text === "string" && text.startsWith(LIST_STAND_IN_MARK);
}

class ListRebuilding extends Error {
  constructor() {
    super(LIST_REBUILDING);
  }
}

// The header tells the conflict guard this 503 is the rebuild (nothing was changed): it asks again
function rebuildingResponse(corsHeaders) {
  return new Response(LIST_REBUILDING, {
    status: 503,
    headers: {
      ...corsHeaders, "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store",
      "Retry-After": "1", "X-Tiddler-List": "rebuilding"
    }
  });
}

// The list entry for a stored tiddler (item: from list()), or null if it isn't listed. Its fields
// come before "text", so usually only the start of the object is read. An object not in the form
// the worker stores (an older version's file, a hand upload) is left out, never guessed at.
async function storedEntry(env, item) {
  const title = item.key.slice(TIDDLER_PREFIX.length);
  if (item.customMetadata?.layout !== FLAT_LAYOUT) {
    console.error(`Rebuilding the tiddler list: ${item.key} isn't stored the way the worker stores tiddlers, left out`);
    return null;
  }
  const read = await readStoredFields(env, item);
  if (!read) return null;
  const { fields, obj } = read;
  if (fields === null || typeof fields !== "object" || Array.isArray(fields)) {
    console.error(`Rebuilding the tiddler list: ${item.key} is not a readable tiddler, left out`);
    return null;
  }
  if (isEphemeralTitle(title) || isDraft(fields)) return null;
  // Listed under the title it's stored under (a save's body always has the same one)
  return listEntry(title, fields, revisionOf(obj), getTwTimestamp(obj.uploaded));
}

// One step of a rebuild. damaged: { object, text } of the list as found (object null if missing).
// Returns null while the rebuild needs more requests, otherwise the list as now stored
// ({ object, text, entries }: rebuilt here, with fresh: true and entries parsed on each access;
// or replaced meanwhile, entries null if still unreadable).
// pageBuild: called by the page build, which builds the page anyway.
async function rebuildList(env, ctx, damaged, { pageBuild = false } = {}) {
  let list = damaged.object;
  if (!list) {
    // Missing: a stand-in takes its place, so this rebuild has a list of its own to replace
    list = await putIfAbsent(env, LIST_KEY, listStandIn(), { httpMetadata: { contentType: "text/plain; charset=utf-8" } });
    if (!list) return getList(env);   // created meanwhile
  }
  // Identifies this damaged list: the same content uploaded again later is another rebuild
  const rebuildId = `${list.etag}/${list.uploaded.getTime()}`;
  const progress = await env.WIKI_BUCKET.get(REPAIR_PROGRESS_KEY);
  const meta = progress?.customMetadata || {};
  const resume = progress !== null && meta.rebuild === rebuildId && Date.now() - progress.uploaded.getTime() < REPAIR_STALE_MS &&
    (meta.cursor !== undefined || meta.after !== undefined);   // a position this version wrote
  const done = resume ? new Uint8Array(await progress.arrayBuffer()) : new Uint8Array(0);
  if (progress && !resume) await progress.body.cancel();   // from another or an abandoned rebuild: start over
  if (!resume && damaged.object && !isListStandIn(damaged.text)) {
    // Kept, in case it holds a hand edit worth redoing
    await env.WIKI_BUCKET.put(`_repair/damaged-tiddler-list-${damaged.object.etag}.json`, damaged.text, {
      httpMetadata: { contentType: "application/json" }
    });
    console.error("The tiddler list can't be read: rebuilding it from the stored tiddlers. The damaged copy is in _repair/.");
  }

  // The next tiddlers, as many as this request can read
  const listing = await env.WIKI_BUCKET.list({
    prefix: TIDDLER_PREFIX, limit: REPAIR_STEP_TIDDLERS, include: ["customMetadata"],
    ...(resume ? (meta.cursor ? { cursor: meta.cursor } : { startAfter: decodeURIComponent(meta.after) }) : {})
  });
  const items = listing.objects;
  const entries = (await mapLimit(items, 6, item => storedEntry(env, item))).filter(Boolean);
  const added = encoder.encode(entries.map(entry => JSON.stringify(entry)).join(","));
  const all = concatBytes(done.length > 0 && added.length > 0 ? [done, encoder.encode(","), added] : [done, added]);
  const count = (resume ? Number(meta.count) || 0 : 0) + entries.length;

  if (listing.truncated) {
    // Only if the damaged list is still there (a request that read it just before another one
    // finished the rebuild would otherwise start a new one)
    if (!resume) {
      const current = await env.WIKI_BUCKET.head(LIST_KEY);
      if (!current || `${current.etag}/${current.uploaded.getTime()}` !== rebuildId) return getList(env);
    }
    // Where the next step starts (list() may return an empty page that isn't the last); the key is
    // encoded, as metadata may be sent as HTTP headers
    const position = items.length > 0 ? { after: encodeURIComponent(items[items.length - 1].key) } : { cursor: listing.cursor };
    const options = { customMetadata: { rebuild: rebuildId, count: String(count), ...position } };
    // Saved only if no other request took this step meanwhile (otherwise its progress stands)
    if (progress) await env.WIKI_BUCKET.put(REPAIR_PROGRESS_KEY, all, { ...options, onlyIf: { etagMatches: progress.etag } });
    else await putIfAbsent(env, REPAIR_PROGRESS_KEY, all, options);
    return null;
  }

  // Every tiddler read: the new list replaces the damaged one, unless it was replaced meanwhile.
  // It's written as is, without parsing it, so the last step costs no more than the others: each
  // key is read once (each step adds to the progress it read, and only if no other request did
  // meanwhile), and each key is one title.
  const text = `[${decoder.decode(all)}]`;
  const written = await env.WIKI_BUCKET.put(LIST_KEY, text, {
    httpMetadata: { contentType: "application/json" },
    onlyIf: { etagMatches: list.etag }
  });
  if (!written) return getList(env);
  if (progress) await env.WIKI_BUCKET.delete(REPAIR_PROGRESS_KEY);
  console.log(`Tiddler list rebuilt: ${count} tiddlers`);
  // Purged now, and again a little later: a public request that read the damaged list or the
  // stand-in just before could otherwise put it back in Cloudflare's cache for a day
  const urls = listPurgeUrls(env);
  ctx.waitUntil(purgePublicCache(env, urls));
  ctx.waitUntil(new Promise(resolve => setTimeout(resolve, waitMs(env, 5000))).then(() => purgePublicCache(env, urls)));
  if (!pageBuild) ctx.waitUntil(markPageOutdated(env));
  // Served as is; parsed only by callers that need the entries (a save, a page build)
  return { object: written, text, fresh: true, get entries() { return parseList(text); } };
}

function failureResponse(what, error, corsHeaders) {
  if (error instanceof ListRebuilding) return rebuildingResponse(corsHeaders);
  return new Response(`${what}: ${error.message}`, { status: error instanceof BadSave ? 400 : 500, headers: corsHeaders });
}

// ===== src/worker/backup/sync.js ==============================================================================

// A full backup, started from the admin wiki (design 1.7): POST /backup/sync queues the job that
// makes GitHub mirror the bucket (queue.js, syncStep), GET /backup/sync says how the last one went.
// For tiddlers that predate the backup (imported before the repository and the token were set), a
// restore, a tiddler put in R2 by hand, or any doubt. Idempotent: run again, it commits nothing.


// A full backup's status as answered, with whether it's running
function jsonResponse(sync, status, corsHeaders) {
  const value = sync && sync.id ? { ...sync, running: syncRunning(sync) } : sync;
  return new Response(JSON.stringify(value), { status, headers: { ...corsHeaders, "Content-Type": "application/json", "Cache-Control": "no-store" } });
}

// POST /backup/sync: 202 with the new full backup's status; 409 with the running one's if there is
// one; 400 without backups, or without the queue the job runs in
async function startBackupSync(request, env, ctx, corsHeaders) {
  if (!github(env)) return refusal("Backups aren't set up: the worker has no GITHUB_REPO and GITHUB_TOKEN (" + guideText("setup", "2.4") + ").", corsHeaders);
  if (!env.BACKUP_QUEUE) return refusal("A full backup runs in the backup queue, which this worker doesn't have (" + guideText("setup", "2.3") + ").", corsHeaders);
  try {
    const status = await readBackupStatus(env, true);
    if (syncRunning(status.sync)) return jsonResponse(status.sync, 409, corsHeaders);
    // The tiddler list says how many there are (a missing or damaged one is rebuilt first, 503 meanwhile)
    const { entries } = await readableList(env, ctx);
    const now = Date.now(), id = `${now}-${crypto.randomUUID().slice(0, 8)}`;
    const start = { id, total: entries.length, done: 0, committed: 0, removed: 0, failed: 0, steps: 0 };
    // Recorded first: a step checks it's the current full backup before working (queue.js)
    let sync = await recordSync(env, { ...start, startedAt: now, phase: "push" }, status);
    try {
      await env.BACKUP_QUEUE.send({ action: "sync", startedAt: now, phase: "push", after: null, time: now, tries: 0, ...start });
    } catch (e) {
      sync = await recordSync(env, { id, finished: now, error: `The queue didn't take the job: ${e.message}` });
      return jsonResponse(sync, 503, corsHeaders);
    }
    return jsonResponse(sync, 202, corsHeaders);
  } catch (error) {
    return failureResponse("Full backup", error, corsHeaders);
  }
}

// GET /backup/sync: the last full backup's status, {} if there never was one
async function backupSyncStatus(env, corsHeaders) {
  const status = await readBackupStatus(env);
  return jsonResponse(status.sync || {}, 200, corsHeaders);
}

// ===== src/worker/app.js ======================================================================================

// The wiki as an installable app (design 1.12): the web app manifest the page links, with the
// wiki's title as its name and the icons inside it; the icons at their own addresses for iOS and
// for the public site; and the copies the public site serves from the bucket.
//
// Behind Cloudflare Access a manifest's icons can't be at addresses: a browser fetches them without
// cookies. So the manifest the worker serves embeds them as data URLs, and the page's link to the
// manifest says use-credentials. The public site has no Access, so its copy in the bucket
// (manifest.webmanifest, written with the page) points at /_app/icon-<size>.png there.


const MANIFEST_KEY = "manifest.webmanifest";
const APP_ICON_SIZES = [192, 512];
const APP_DIR = "_app/";
const THEME_COLOR = "#2d6a8f";
const BACKGROUND_COLOR = "#f4f4f4";
const DEFAULT_NAME = "My TiddlyWiki";   // TiddlyWiki's own site title, until the wiki's is set
const SHORT_NAME_LIMIT = 12;

// The default icons (src/app/, embedded by the build as base64)
const DEFAULT_ICONS = { 192: "", 512: "" };

// What the page's <head> carries: the manifest, with the site's cookies, the theme colour, the
// iOS icon (Safari reads no manifest icons)
const APP_HEAD = `<link rel="manifest" href="/${MANIFEST_KEY}" crossorigin="use-credentials">\n<meta name="theme-color" content="${THEME_COLOR}">\n<link rel="apple-touch-icon" href="/${APP_DIR}icon-192.png">`;

function iconKey(size) {
  return `${APP_DIR}icon-${size}.png`;
}

// The wiki's title: the stored $:/SiteTitle, or TiddlyWiki's own
async function siteTitle(env) {
  try {
    const stored = await env.WIKI_BUCKET.get(tiddlerKey("$:/SiteTitle"));
    if (!stored) return DEFAULT_NAME;
    const fields = await stored.json();
    const text = typeof fields.text === "string" ? fields.text.trim() : "";
    return text || DEFAULT_NAME;
  } catch {
    return DEFAULT_NAME;
  }
}

// An icon's bytes, base64: the owner's from the bucket, else the default
async function iconBase64(env, size) {
  try {
    const own = await env.WIKI_BUCKET.get(iconKey(size));
    if (own) return bytesToBase64(new Uint8Array(await own.arrayBuffer()));
  } catch {}
  return DEFAULT_ICONS[size];
}

function bytesToBase64(bytes) {
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  return btoa(binary);
}

function base64ToBytes(base64) {
  const binary = atob(base64), bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

// The manifest, with the icons as data URLs (the worker's, behind Access) or at their addresses
// (the public site's copy)
async function manifestJson(env, { embedIcons }) {
  const name = await siteTitle(env);
  const icons = await Promise.all(APP_ICON_SIZES.map(async size => ({
    src: embedIcons ? `data:image/png;base64,${await iconBase64(env, size)}` : `/${iconKey(size)}`,
    sizes: `${size}x${size}`,
    type: "image/png",
    purpose: "any maskable"
  })));
  const manifest = { name, start_url: "/", scope: "/", display: "standalone", background_color: BACKGROUND_COLOR, theme_color: THEME_COLOR, icons };
  if (name.length <= SHORT_NAME_LIMIT) manifest.short_name = name;
  return JSON.stringify(manifest);
}

const MANIFEST_TYPE = "application/manifest+json";

// GET /manifest.webmanifest: the worker's, for the admin site; cached a day by the browser, which
// asks for it at installs and launches
async function serveManifest(env, corsHeaders) {
  const body = await manifestJson(env, { embedIcons: true });
  return new Response(body, { headers: { ...corsHeaders, "Content-Type": `${MANIFEST_TYPE}; charset=utf-8`, "Cache-Control": "private, max-age=86400" } });
}

// GET /_app/icon-<size>.png: the owner's icon from the bucket, else the default
async function serveIcon(env, size, corsHeaders) {
  const headers = { ...corsHeaders, "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" };
  try {
    const own = await env.WIKI_BUCKET.get(iconKey(size));
    if (own) return new Response(own.body, { headers });
  } catch {}
  return new Response(base64ToBytes(DEFAULT_ICONS[size]), { headers });
}

// With each page build: the public site's copy of the manifest, written when it's missing or the
// page's source changed (the title lives in the published page), one look otherwise; the default
// icons go in with the first manifest ever written, unless the owner has put some. Purged from the
// public cache when written.
async function ensureAppFiles(env, ctx, pageSource) {
  const source = `${pageSource.index}:${pageSource.fingerprint || ""}`;
  const written = [];
  try {
    const existing = await env.WIKI_BUCKET.head(MANIFEST_KEY);
    if (existing && existing.customMetadata?.source === source) return;
    if (!existing) {
      for (const size of APP_ICON_SIZES) {
        if (!await env.WIKI_BUCKET.head(iconKey(size))) {
          await env.WIKI_BUCKET.put(iconKey(size), base64ToBytes(DEFAULT_ICONS[size]), { httpMetadata: { contentType: "image/png", cacheControl: "public, max-age=86400" } });
        }
      }
    }
    await env.WIKI_BUCKET.put(MANIFEST_KEY, await manifestJson(env, { embedIcons: false }), { httpMetadata: { contentType: MANIFEST_TYPE, cacheControl: "public, max-age=86400" }, customMetadata: { source } });
    written.push(`/${MANIFEST_KEY}`);
  } catch (e) {
    console.error("The app's files couldn't be written:", e.message);
  }
  if (written.length && purges(env)) ctx.waitUntil(purgePublicCache(env, written.map(path => publicUrl(env, path))));
}

// ===== src/worker/plugins.js ==================================================================================

// Plugin files (design 1.8): _plugins/<title>.js holds the stored tiddler, untouched, inside the
// same code the external-plugins export template produces: it adds the tiddler to
// $tw.preloadTiddlers before TiddlyWiki boots. The file name never changes; the page loads it as
// <title>.js?v=<revision>, so every version has its own URL and nothing needs purging. Files are
// served by the public site, never by the worker.


const PRELOAD_OPEN = "{\nconst tw = globalThis.$tw ??= Object.create(null);\ntw.preloadTiddlers = (tw.preloadTiddlers ?? []).concat([";

const PRELOAD_CLOSE = "]);\n}\n";

// A tiddler with a field called "fields" (stored nested: hasNestedFields) is unpacked first
const PRELOAD_NESTED_OPEN = "{\nconst t = ";

const PRELOAD_NESTED_CLOSE = ";\nt.fields = t.fields.fields;\nconst tw = globalThis.$tw ??= Object.create(null);\ntw.preloadTiddlers = (tw.preloadTiddlers ?? []).concat([t]);\n}\n";

function pluginFileKey(title) {
  return `${PLUGIN_FILE_DIR}${title}.js`;
}

// Encoded the same way as the tiddler URLs the public wiki already loads; on the public site, or
// root-relative (this site, the worker) for a private wiki
function pluginFileUrl(env, title, revision) {
  return publicUrl(env, `/${PLUGIN_FILE_DIR}${encodeURIComponent(title)}.js?v=${encodeURIComponent(revision)}`);
}

// Writes the plugin file from the stored tiddler. entry: its list entry; file: what head()
// returned for the file (or null).
// Two page builds can overlap, so it doesn't replace a file holding a newer version, and writes
// only if the file is still the one it looked at. After two lost races, a missing file is written
// unconditionally (like the PUT handler's create-only fallback): best effort, not a guarantee.
// Returns the revision the file holds, or null.
async function writePluginFile(env, entry, file) {
  const title = entry.title;
  const obj = await env.WIKI_BUCKET.get(tiddlerKey(title));
  if (!obj) return null;
  const revision = revisionOf(obj);
  const nested = hasNestedFields(entry);
  const content = concatBytes([
    encoder.encode(nested ? PRELOAD_NESTED_OPEN : PRELOAD_OPEN), new Uint8Array(await obj.arrayBuffer()), encoder.encode(nested ? PRELOAD_NESTED_CLOSE : PRELOAD_CLOSE)
  ]);
  const key = pluginFileKey(title);
  for (let attempt = 1; attempt <= 3; attempt++) {
    const held = file?.customMetadata?.revision;
    if (held && (held === revision || isNewerRevision(held, revision))) return held;
    const options = {
      httpMetadata: { contentType: "text/javascript; charset=utf-8", cacheControl: "public, max-age=31536000, immutable" },
      customMetadata: { revision }
    };
    // Create-only if missing; on the last try, a missing file is written whatever happens
    if (file) options.onlyIf = { etagMatches: file.etag };
    else if (attempt < 3) options.onlyIf = new Headers({ "If-None-Match": "*" });
    if (await env.WIKI_BUCKET.put(key, content, options)) return revision;
    file = await env.WIKI_BUCKET.head(key);   // another build wrote it meanwhile: look again
  }
  return file?.customMetadata?.revision ?? null;
}

// Makes sure each listed plugin's file holds its current version (writing it if not) and returns
// the <script> tags that load them, in the order of the tiddler list. Disabled plugins are loaded
// too: their disable flag is baked into the page, so TiddlyWiki skips them at boot. (Leaving them
// out would make the sync fetch them after boot, and TiddlyWiki would then ask for a reload.)
async function pluginScriptTags(env, entries) {
  const tags = await Promise.all(entries.map(async (entry) => {
    const file = await env.WIKI_BUCKET.head(pluginFileKey(entry.title));
    let revision = file?.customMetadata?.revision;
    if (!revision || revision !== String(entry.revision)) {
      revision = await writePluginFile(env, entry, file);
    }
    return revision ? `<script src="${pluginFileUrl(env, entry.title, revision)}"></script>` : "";
  }));
  return tags.filter(Boolean).join("\n");
}

// After the page has been rebuilt without it, so a page load in between doesn't miss it. If this
// fails, the file is only left behind (nothing loads it): the request isn't failed for it, since its
// retry would find nothing left to do, and wouldn't rebuild the page either
async function deletePluginFile(env, title) {
  try {
    await env.WIKI_BUCKET.delete(pluginFileKey(title));
  } catch (e) {
    console.error(`Could not delete the plugin file of '${title}' (left behind, unused):`, e.message);
  }
}

// ===== src/worker/build.js ====================================================================================

// Building the page, baked.html (design 1.3): the page source (the published shell, or index.html)
