const SW_URL_TITLE = "$:/cfworker/sw-url";
let serviceWorkerVersion = "";

function swVersion() {
  if (!serviceWorkerVersion) serviceWorkerVersion = "1-" + hashText(SERVICE_WORKER_SOURCE).toString(36);
  return serviceWorkerVersion;
}

// GET /sw.js: the service worker script. The browser checks the script of a registration at
// navigations, from its cache while the script is fresh (a day here), past it afterwards: so a
// page load costs no request for it, and a new version has a new address anyway (the page's).
function serveServiceWorker(request, corsHeaders) {
  const etag = `"sw-${swVersion()}"`;
  const headers = { ...corsHeaders, "Content-Type": "application/javascript; charset=utf-8", "Cache-Control": "private, max-age=86400", ETag: etag };
  if ((request.headers.get("If-None-Match") || "").includes(etag)) return new Response(null, { status: 304, headers });
  return new Response(SERVICE_WORKER_SOURCE, { headers });
}

function hashText(text) {
  let hash = 5381;
  for (let i = 0; i < text.length; i++) {
    hash = ((hash * 33) ^ text.charCodeAt(i)) >>> 0;
  }
  return hash;
}

// Their settings. The public site's address: the admin wiki loads tiddler contents from there (no
// worker request) and only asks the worker when that copy isn't current. Empty for a private wiki
// (setup 2.1): the modules then know this site is the admin site, and read from the worker.
const PUBLIC_URL_TITLE = "$:/cfworker/public-url";

// What the page carries as the public address: the site with a trailing slash, or ""
function publicAddress(env) {
  return publicSite(env) ? publicUrl(env, "/") : "";
}

// What the page was built from, so the page publisher can tell when it needs publishing again
const PAGE_SOURCE_TITLE = "$:/cfworker/page-source";

// The modules and their settings travel as one plugin (design 2.21), $:/plugins/cfworker/admin:
// its parts are shadow tiddlers (out of search, out of syncing, overridden only on purpose), and
// Control Panel → Plugins lists it with the worker's version (package.json's, plus the hash of
// everything else in it: pluginVersion) and three tabs, a readme, the settings and the device
// (src/browser/*.txt).
// Preloaded like the modules were: never stored, never a plugin file (tiddlers.js, page-publisher.js).
const ADMIN_PLUGIN_TITLE = "$:/plugins/cfworker/admin";
const PACKAGE_VERSION = "2026.10.19";   // filled by build.mjs from package.json
const SHIPPED_VERSION = "5.4.1";   // the TiddlyWiki version of the empty wiki the worker ships (build.mjs)
const PLUGIN_README_SOURCE = "The admin wiki's side of [[TiddlyWiki on Cloudflare|https://github.com/DesignThinkerer/tiddlywiki-cloudflare]]: the conflict guard, the tiddler list and the device copy, the backup alert, the page publisher, the restore import, the Cloudflare tab (Saving), the outbox (editing offline) and the service worker (opening offline).\n\nThe worker puts it in every page it builds: it always matches the worker, whose version is above, and isn't stored in the wiki. A part edited here is an override, as with any plugin, and stays until deleted.\n\nSettings: the //settings// tab. What this browser keeps, and forgetting it: the //device// tab. The worker's own settings (the public site, backups, purges): the Cloudflare dashboard, [[setup 2.5|https://github.com/DesignThinkerer/tiddlywiki-cloudflare/blob/main/docs/setup.md#25-the-worker]].\n";
const PLUGIN_SETTINGS_SOURCE = "Settings are saved in the wiki (`$:/config/…`), so they apply on every device. For what each one trades, see [[operating 3.17|https://github.com/DesignThinkerer/tiddlywiki-cloudflare/blob/main/docs/operating.md#317-the-plugin-and-its-settings]].\n\n! Settings\n\n<$checkbox tiddler=\"$:/config/cfworker/LoadAll\" field=\"text\" checked=\"yes\" unchecked=\"no\" default=\"yes\"> Load all tiddlers in the background</$checkbox> — text search and backlinks then see everything. If unchecked, a tiddler is loaded when shown. ''(Requires page reload)''\n\n<$edit-text tiddler=\"$:/config/SyncPollingInterval\" tag=\"input\" type=\"number\" default=\"\" placeholder=\"60000\" size=\"8\"/> ms — Sync polling interval: time between an open tab's checks for updated tiddlers. Each check is one Worker request (TiddlyWiki core setting). ''(Requires page reload)''\n\n! Advanced\n\n''The defaults fit the Cloudflare free plan and are what the tests run. Modify with caution.'' Leave a field empty to use the default value in parentheses.\n\n* <$edit-text tiddler=\"$:/config/cfworker/DraftPause\" tag=\"input\" type=\"number\" default=\"\" placeholder=\"300\" size=\"6\"/> ms of typing inactivity before a draft is saved locally (300)\n* <$edit-text tiddler=\"$:/config/cfworker/FetchAhead\" tag=\"input\" type=\"number\" default=\"\" placeholder=\"6\" size=\"6\"/> tiddlers fetched concurrently during background loading (6; 1 at least)\n* <$edit-text tiddler=\"$:/config/cfworker/PublishPause\" tag=\"input\" type=\"number\" default=\"\" placeholder=\"1000\" size=\"6\"/> ms after a save before the page is published (1000)\n* <$edit-text tiddler=\"$:/config/cfworker/BackupCheckMinutes\" tag=\"input\" type=\"number\" default=\"\" placeholder=\"60\" size=\"6\"/> minutes between backup status checks (60)\n* <$edit-text tiddler=\"$:/config/cfworker/NetworkWait\" tag=\"input\" type=\"number\" default=\"\" placeholder=\"8\" size=\"6\"/> seconds the service worker waits for the network before serving the page it kept (8). ''(Requires page reload)''\n";
const PLUGIN_DEVICE_SOURCE = "What this browser keeps of the wiki, for opening and editing offline ([[operating 3.13|https://github.com/DesignThinkerer/tiddlywiki-cloudflare/blob/main/docs/operating.md#313-opening-the-wiki-offline]]): the device copy (the tiddlers loaded here), the outbox (the changes not yet sent) and the service worker's files. Nothing here asks the worker anything.\n\n<$button message=\"tm-cfworker-device-measure\">Measure</$button>\n\n<$list filter=\"[[$:/temp/cfworker/device]has[text]]\" variable=\"measured\">\n\n{{$:/temp/cfworker/device}}\n\n</$list>\n\n! Keeping it\n\nA browser short of space may clear a site's storage, a change waiting in the outbox with it, unless it has promised to keep it. Firefox asks you; Chrome and Safari decide by their own rules (a site used often, installed or bookmarked) and answer at once.\n\n<$list filter=\"[[$:/temp/cfworker/outbox]get[storage]match[persistent]]\" variable=\"kept\">This browser has promised to keep this site's data.</$list><$list filter=\"[[$:/temp/cfworker/outbox]get[storage]!match[persistent]]\" variable=\"notyet\"><$button message=\"tm-cfworker-device-keep\">Ask the browser to keep this site's data</$button></$list>\n\n<$list filter=\"[[$:/temp/cfworker/device-message]field:about[keep]]\">\n\n<$transclude mode=\"block\"/>\n\n</$list>\n\n! Forgetting it\n\nRemoves the device copy, the outbox and the service worker's files from this browser, then reloads: the wiki comes back from the worker and the copy fills again, as on a new device. Refused while a change or a draft waits in the outbox, and while the worker doesn't answer (the page comes back from it once the copy is gone).\n\n<$button message=\"tm-cfworker-device-forget\">Forget this device's copy</$button>\n\n<$list filter=\"[[$:/temp/cfworker/device-message]field:about[forget]]\">\n\n<$transclude mode=\"block\"/>\n\n</$list>\n";
const PLUGIN_FIELDS = {
  name: "TiddlyWiki on Cloudflare", description: "The admin wiki's side of the worker: conflicts, the tiddler list and the device copy, backups, the published page, editing and opening offline",
  author: "https://github.com/DesignThinkerer/tiddlywiki-cloudflare", "core-version": ">=5.3.0", list: "readme settings device"
};
let adminPluginVersion = "";

// package.json's version, plus the hash of everything else in the plugin that doesn't depend on
// the wiki: the modules, the service worker's address, the three tabs and the fields above. So the
// version changes whenever any of them does, and the page, which carries the plugin, is rebuilt
// (bakeVersion). Worked out once while the worker runs.
function pluginVersion() {
  if (!adminPluginVersion) {
    // (The shipped TiddlyWiki version is in the page too, for the Cloudflare tab: a new one, a new page)
    const parts = [...BROWSER_MODULES.map(m => m.source), swVersion(), PLUGIN_README_SOURCE, PLUGIN_SETTINGS_SOURCE, PLUGIN_DEVICE_SOURCE, JSON.stringify(PLUGIN_FIELDS), SHIPPED_VERSION];
    adminPluginVersion = PACKAGE_VERSION + "+" + hashText(parts.join("\n")).toString(36);
  }
  return adminPluginVersion;
}

function adminPlugin(env, pageSource) {
  const tiddlers = {};
  for (const m of BROWSER_MODULES) tiddlers[m.title] = { title: m.title, type: "application/javascript", "module-type": m.type, text: m.source };
  tiddlers[PUBLIC_URL_TITLE] = { title: PUBLIC_URL_TITLE, text: publicAddress(env) };
  tiddlers[SW_URL_TITLE] = { title: SW_URL_TITLE, text: `/sw.js?v=${swVersion()}` };
  tiddlers[PAGE_SOURCE_TITLE] = { title: PAGE_SOURCE_TITLE, type: "application/json", text: JSON.stringify({ index: pageSource.index, fingerprint: pageSource.fingerprint, core: pageSource.core, shell: pageSource.shell || "", engine: engineVersion(pageSource.html), shipped: SHIPPED_VERSION }) };
  tiddlers[`${ADMIN_PLUGIN_TITLE}/readme`] = { title: `${ADMIN_PLUGIN_TITLE}/readme`, text: PLUGIN_README_SOURCE };
  tiddlers[`${ADMIN_PLUGIN_TITLE}/settings`] = { title: `${ADMIN_PLUGIN_TITLE}/settings`, text: PLUGIN_SETTINGS_SOURCE };
  tiddlers[`${ADMIN_PLUGIN_TITLE}/device`] = { title: `${ADMIN_PLUGIN_TITLE}/device`, text: PLUGIN_DEVICE_SOURCE };
  return {
    title: ADMIN_PLUGIN_TITLE, "plugin-type": "plugin", type: "application/json", ...PLUGIN_FIELDS, version: pluginVersion(),
    text: JSON.stringify({ tiddlers })
  };
}

// Changes whenever the plugin (pluginVersion: the modules, the service worker, the tabs, the fields,
// the package version) or the public URL changes, so baked.html is rebuilt after a deploy that
// changes what the page carries, and not after one that doesn't (the number in front changes when
// the way pages are built changes). Asked at every page load: worked out once while the worker
// runs (hashing the modules costs about 0.3 ms), again only if its settings change.
let lastBakeVersion = { settings: null, version: "" };

function bakeVersion(env) {
  const enabled = conflictGuardEnabled(env), settings = enabled + "\n" + publicAddress(env);
  if (lastBakeVersion.settings !== settings) {
    const input = (enabled ? pluginVersion() : "off") + "\n" + publicAddress(env);
    lastBakeVersion = { settings, version: "9-" + hashText(input).toString(36) };
  }
  return lastBakeVersion.version;
}

// The page's ETag is "<baked.html's R2 etag>-page". The browser asks with it (If-None-Match, maybe
// weakened to W/ by Cloudflare's compression), and an unchanged page answers 304: nothing to
// download, and its body isn't even read from R2.
// Cloudflare features that rewrite HTML remove the ETag on the way out, and one of them (Replace
// insecure JavaScript libraries) is on by default on the Free plan and can only be turned off for
// the whole zone. So the page also has a Last-Modified date, which they keep: the browser then
// asks with If-Modified-Since. The date is the page's version (pageTime, in seconds, set when it's
// stored, later than the previous page's even within the same second), and it has to match exactly.
const PAGE_ETAG_SUFFIX = "-page";

// Inserts markup right after <head ...>. Works on the bytes of index.html (a few MB): decoding,
// editing and re-encoding the whole page as a string costs about ten times more CPU.
const pageDecoder = new TextDecoder("utf-8", { fatal: false, ignoreBOM: true });

// The TiddlyWiki version a page (index.html, or the shell rendered from it) was made by: its
// <meta name="tiddlywiki-version"> tag, in the head; "" when there's none. Looked for in the first
// 64 KB (bytes or a string).
function engineVersion(html) {
  const head = typeof html === "string" ? html.slice(0, 65536) : pageDecoder.decode(html.subarray(0, Math.min(html.length, 65536)));
  const match = /<meta\s+name="tiddlywiki-version"\s+content="([^"]*)"/i.exec(head);
  return match ? match[1] : "";
}

function insertAfterHead(html, markup) {
  for (const length of [16384, html.length]) {
    const start = pageDecoder.decode(html.subarray(0, length));
    const match = /<head[^>]*>/i.exec(start);
    if (match) {
      const at = encoder.encode(start.slice(0, match.index + match[0].length)).length;
      return concatBytes([html.subarray(0, at), encoder.encode(markup), html.subarray(at)]);
    }
    if (length >= html.length) break;
  }
  return html;
}

// A byte offset moved back to the start of a character, so a window never cuts one in two
function charStart(bytes, at) {
  while (at > 0 && at < bytes.length && (bytes[at] & 0xC0) === 0x80) at--;
  return at;
}

// Inserts markup right before the last occurrence of marker, looked for in the page's last 64 KB
// (all of it if it isn't there). Returns the new bytes, or null if the page doesn't have it.
function insertBeforeLast(html, marker, markup) {
  for (const length of [65536, html.length]) {
    const from = charStart(html, Math.max(0, html.length - length));
    const tail = pageDecoder.decode(html.subarray(from));
    const index = tail.lastIndexOf(marker);
    if (index >= 0) {
      const at = from + encoder.encode(tail.slice(0, index)).length;
      return concatBytes([html.subarray(0, at), encoder.encode(markup), html.subarray(at)]);
    }
    if (from === 0) break;
  }
  return null;
}

// Saves baked.html, unless an overlapping build has already saved a newer one for the same worker
// and index.html: from a newer tiddler list or a newer shell, and no older one of the other.
// "Newer" compares when R2 stored each (listVersion, shellVersion), so a list replaced by hand
// counts as newer too. If each page has the newer one of the two (a rare three-way overlap), this
// one is stored as outdated, so the next page load builds it from both. Each page gets its date
// (pageTime, see serveWiki). Returns the stored page (its R2 object), or null if it kept the other
// page. The last try writes unconditionally, like the create-only fallback in the PUT handler: best
// effort.
async function storePage(env, html, meta) {
  for (let attempt = 1; attempt <= 3; attempt++) {
    const current = await env.WIKI_BUCKET.head(PAGE_KEY);
    const theirs = current?.customMetadata || {};
    let stored = meta;
    if (current && theirs.bakeVersion === meta.bakeVersion && theirs.sourceEtag === meta.sourceEtag) {
      const newerList = Number(theirs.listVersion) - Number(meta.listVersion),
        newerShell = Number(theirs.shellVersion || 0) - Number(meta.shellVersion);
      if (newerList >= 0 && newerShell >= 0 && (newerList > 0 || newerShell > 0)) return null;
      if (newerList > 0 || newerShell > 0) stored = { ...meta, bakeVersion: "outdated" };
    }
    const pageTime = Math.max(Math.floor(Date.now() / 1000), Number(theirs.pageTime || 0) + 1);
    const written = await env.WIKI_BUCKET.put(PAGE_KEY, html, {
      httpMetadata: { contentType: "text/html; charset=utf-8" },
      customMetadata: { ...stored, pageTime: String(pageTime) },
      ...(current && attempt < 3 ? { onlyIf: { etagMatches: current.etag } } : {})
    });
    if (written) return written;
  }
  return null;
}

// What the page preloads ($tw.preloadTiddlers): the listed startup tiddlers, read from the bucket
// (every stored tiddler is listed, so only listed ones are read), and the admin plugin (the browser
// modules with their settings), unless CONFLICT_GUARD is off
async function preloadedTiddlers(env, entries, pageSource) {
  const store = [];
  const startupTitles = entries.filter(t => t.title && isStartupTiddler(t)).map(t => t.title);
  await Promise.all(startupTitles.map(async (title) => {
    const obj = await env.WIKI_BUCKET.get(tiddlerKey(title));
    if (!obj) return;
    try {
      const tiddler = await obj.json();
      if (hasNestedFields(tiddler)) tiddler.fields = tiddler.fields.fields;
      store.push(tiddler);
    } catch (e) {}
  }));
  if (conflictGuardEnabled(env)) store.push(adminPlugin(env, pageSource));
  return store;
}

// The page source with the preloaded tiddlers (as a script right after <head>) and the plugin
// script tags in it. In a shell, plugins load right before the core (they must run before
// TiddlyWiki starts, which the core does), so they don't hold up the top of the page (a splash
// screen). In a full index.html, where TiddlyWiki starts from code inside the page, from <head>.
// (Only a shell is searched: in index.html, the marker is only in TiddlyWiki's templates, so the
// search would decode the whole page for nothing, and one in raw markup isn't the place.)
function pageWithPreloads(pageSource, store, pluginTags) {
  let html = pageSource.html;
  let pluginsPlaced = false;
  if (pluginTags && pageSource.fingerprint) {
    const placed = insertBeforeLast(html, EXTERNAL_SCRIPTS_MARKER, `${pluginTags}\n`);
    if (placed) {
      html = placed;
      pluginsPlaced = true;
    }
  }
  let injected = "";
  if (store.length > 0) {
    const safeJson = JSON.stringify(store).replace(/</g, '\\u003c');
    injected = `
        <script>
          window.$tw = window.$tw || {};
          window.$tw.preloadTiddlers = window.$tw.preloadTiddlers || [];
          window.$tw.preloadTiddlers = window.$tw.preloadTiddlers.concat(${safeJson});
        </script>
      `;
  }
  if (pluginTags && !pluginsPlaced) injected += `\n${pluginTags}\n`;
  // The app's manifest and icon, for the browser to install the wiki (app.js)
  injected += `\n${APP_HEAD}\n`;
  html = insertAfterHead(html, `\n${injected}\n`);
  return html;
}

// Builds baked.html = the page source (the published shell, or index.html, see readPageSource) +
// startup tiddlers + browser modules + plugin <script> tags, then purges the public copy. source:
// the page source, if the caller has it. Returns { html (bytes), page: the stored page's R2 object,
// or null if an overlapping build's page was kept }, or null.
async function rebakeHtml(env, ctx, list = null, source = null) {
  try {
    const pageSource = source || await readPageSource(env);
    if (!pageSource) return null;
    // list: the list a save or delete has just written. Otherwise it's read, and a missing or
    // damaged one rebuilt first (a page built without it would have no plugins); while that takes
    // more requests, this throws and the page stays as it is.
    const { object: listObject, entries } = list || await readableList(env, ctx, { pageBuild: true });
    const [store, pluginTags] = await Promise.all([
      preloadedTiddlers(env, entries, pageSource),
      pluginScriptTags(env, entries.filter(t => t.title && needsPluginFile(t)))
    ]);
    const html = pageWithPreloads(pageSource, store, pluginTags);
    const stored = await storePage(env, html, {
      bakeVersion: bakeVersion(env),
      sourceEtag: pageSource.index,
      shell: pageSource.fingerprint,
      shellVersion: String(pageSource.shellVersion || 0),
      listVersion: String(listObject ? listObject.uploaded.getTime() : 0)
    });
    if (stored) ctx.waitUntil(purgePublicCache(env, PUBLIC_PAGE_PATHS.map(path => publicUrl(env, path))));
    // The public site's manifest and icons, beside the page (finished even if the request ends first)
    ctx.waitUntil(ensureAppFiles(env, ctx, pageSource));
    return { html, page: stored };
  } catch (err) {
    console.error("Failed to rebake HTML:", err);
    return null;
  }
}

// What a page is built from: { html (bytes), index: index.html's ETag, fingerprint: the shell's
// ("" for index.html itself), core: the stored core file's version ("" if none), shell: the stored
// shell's ETag ("" for index.html itself, unless a stored shell was passed over: then its ETag, the
// version the next one replaces), the version a tab sends back with the page it publishes
// (publishShell) }, or null if there's no index.html.
// The shell is used while it's the one published for this index.html and loads the core file from
// where the page would (coreFileUrl: the public site, or this site for a private wiki). After a
// change of the public address, the shell published for the old one names it in the core's script
// tag: built from, both sites would load the core from a site that may be gone, and the admin wiki,
// unable to start, would never publish another. It's passed over, and the page built from index.html
// until the admin wiki publishes a shell for the new address, at its next load (design 1.9).
async function readPageSource(env) {
  const [index, shell, coreFile] = await Promise.all([
    env.WIKI_BUCKET.head(INDEX_KEY), env.WIKI_BUCKET.get(SHELL_KEY), env.WIKI_BUCKET.head(CORE_KEY)
  ]);
  const core = coreFile?.customMetadata?.v || "";
  const kept = shell && index && shell.customMetadata?.index === index.etag ? shell : null;
  if (kept) {
    const html = new Uint8Array(await kept.arrayBuffer());
    if (loadsCoreFile(html, env, core)) {
      return { html, index: index.etag, fingerprint: kept.customMetadata.fingerprint || "", core, shellVersion: kept.uploaded.getTime(), shell: kept.etag };
    }
    console.log("The published page loads the core file from elsewhere than the public site (or this site, for a private wiki): the page is built from index.html until the admin wiki publishes it again");
  } else if (shell) await shell.body.cancel();
  const full = await env.WIKI_BUCKET.get(INDEX_KEY);
  return full && { html: new Uint8Array(await full.arrayBuffer()), index: full.etag, fingerprint: "", core, shell: kept ? kept.etag : "" };
}

// Whether a shell loads the stored core file from where the page would: its script tag is at the end
// of the page, so the last 64 KB are looked at (what publishShell checked on the whole shell)
function loadsCoreFile(html, env, version) {
  if (!version) return false;
  const from = charStart(html, Math.max(0, html.length - 65536));
  return pageDecoder.decode(html.subarray(from)).includes(`<script src="${coreFileUrl(env, version)}"`);
}

// Where the page loads the core file from: the public site, or this site (root-relative) for a
// private wiki. The page publisher writes the same URL into the shell (page.js checks it).
function coreFileUrl(env, version) {
  return publicUrl(env, `/${CORE_KEY}?v=${encodeURIComponent(version)}`);
}

const EXTERNAL_SCRIPTS_MARKER = "<!--~~ Load external JavaScripts ~~-->";

// ===== src/worker/page.js =====================================================================================

// Serving the page, and the page the admin wiki publishes (design 1.3, 1.9).
//
// The admin wiki renders the page itself, with TiddlyWiki's own template
// $:/core/templates/tiddlywiki5-external-js.html (src/browser/page-publisher.js): the shell, which is
// everything TiddlyWiki writes in its file (title, language, raw markup...) but the core, and the
// core file, loaded at the end of the shell. The shell is kept in _page/shell.html, with the
// index.html it was rendered for; the page is built from it while that's the current index.html,
// and from index.html itself otherwise (a new upload, until the admin wiki publishes a shell for
// it). index.html is never changed. The core file is _plugins/tiddlywikicore.js, served by the
// public site as ?v=<TiddlyWiki version>-<format> and cached for a year, like plugin files.


function pageHeaders(htmlHeaders, page) {
  const headers = { ...htmlHeaders, ETag: `"${page.etag}${PAGE_ETAG_SUFFIX}"` };
  const time = Number(page.customMetadata?.pageTime);
  if (time) headers["Last-Modified"] = new Date(time * 1000).toUTCString();
  return headers;
}

// X-Wiki-Page marks the page as the worker's own: the service worker (design 1.11) keeps only an
// answer that carries it, never Cloudflare's login page or a refusal
async function serveWiki(request, env, ctx, corsHeaders) {
  const htmlHeaders = { ...corsHeaders, "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-cache", "X-Wiki-Page": bakeVersion(env) };
  const ifNoneMatch = request.headers.get("If-None-Match");
  const known = parseEtagList(ifNoneMatch).find(token => token.endsWith(PAGE_ETAG_SUFFIX));
  // Only without an ETag, as HTTP says
  const since = ifNoneMatch ? NaN : Math.floor(Date.parse(request.headers.get("If-Modified-Since") || "") / 1000);
  let [baked, source] = await Promise.all([
    env.WIKI_BUCKET.get(PAGE_KEY, known ? { onlyIf: { etagDoesNotMatch: known.slice(0, -PAGE_ETAG_SUFFIX.length) } } : undefined),
    env.WIKI_BUCKET.head(INDEX_KEY)
  ]);
  // A new bucket, or an engine deleted by hand: the empty wiki the build made goes there first
  if (!source && await seedWiki(env)) source = await env.WIKI_BUCKET.head(INDEX_KEY);
  if (baked) {
    const meta = baked.customMetadata || {};
    // A conditional get whose precondition fails returns the object without a body: the browser has it
    const hasBody = "body" in baked;
    if (!source || (meta.bakeVersion === bakeVersion(env) && meta.sourceEtag === source.etag)) {
      const headers = pageHeaders(htmlHeaders, baked);
      if (hasBody && since !== Number(meta.pageTime)) return new Response(baked.body, { headers });
      if (hasBody) await baked.body.cancel();
      return new Response(null, { status: 304, headers });
    }
    if (hasBody) await baked.body.cancel();
  }
  // (Finished even if the browser goes away first: a reload while it builds, say)
  const rebuilt = await untilDone(ctx, rebakeHtml(env, ctx));
  // With its ETag and date, so the next load is already a 304 (unless another build's page was kept)
  if (rebuilt) return new Response(rebuilt.html, { headers: rebuilt.page ? pageHeaders(htmlHeaders, rebuilt.page) : htmlHeaders });
  // The rebuild failed (see the logs): the last page built is better than the bare engine
  const lastPage = baked && await env.WIKI_BUCKET.get(PAGE_KEY);
  if (lastPage) return new Response(lastPage.body, { headers: htmlHeaders });
  const fallback = await env.WIKI_BUCKET.get(INDEX_KEY);
  if (!fallback) return new Response(NO_WIKI, { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" } });
  return new Response(fallback.body, { headers: htmlHeaders });
}

// A new bucket is empty. The build makes seed/empty.html, an empty TiddlyWiki with the TiddlyWeb
// plugin, which a deploy through Wrangler or Workers Builds uploads with the worker as a text module
// (wrangler.toml): the first page request puts it in the bucket as index.html, with the public
// site's status file, and the wiki starts from there. Nothing already in the bucket is replaced, so
// an engine deleted by hand gets a fresh one and the stored tiddlers stay. The empty tiddler list
// isn't written: the first list request makes it from the stored tiddlers (none, or the ones that
// stayed). A worker pasted into the dashboard has no such module: the page then says what to upload.
// (A module, not a static asset: a worker with static assets runs behind a router that doesn't pass
// Cloudflare Access's mark on to it, see access.js.) Loaded only here, when a bucket needs it.

const PUBLIC_STATUS = { username: "GUEST", read_only: true, anonymous: true, logout_is_available: false, space: { recipe: "default" } };

const NO_WIKI = "There's no wiki yet: the bucket has no index.html, and this worker was deployed without the empty wiki that would " +
  "go there by itself (a deploy through Wrangler or Workers Builds ships it, " + guideText("setup", "2.8") + "). Upload an index.html, a TiddlyWiki " +
  "with the TiddlyWeb plugin, and the status file (setup 2.8), then open this page again.";

// The empty wiki module, or null without it (logged)
async function loadSeed() {
  let html;
  try {
    ({ default: html } = await import("./seed/empty.html"));   // (a literal: Miniflare resolves the module from it)
  } catch (e) {
    console.error("The empty wiki isn't among the worker's modules (a pasted worker.js?):", e.message);
    return null;
  }
  if (typeof html !== "string" || !html) {
    console.error("The empty wiki module is empty: the build didn't make seed/empty.html?");
    return null;
  }
  return html;
}

async function seedWiki(env) {
  const html = await loadSeed();
  if (!html) return false;
  const index = await putIfAbsent(env, INDEX_KEY, html, { httpMetadata: { contentType: "text/html; charset=utf-8" } });
  const status = await putIfAbsent(env, STATUS_KEY, JSON.stringify(PUBLIC_STATUS), { httpMetadata: { contentType: "application/json" } });
  // (Either may have been there: the status file kept when the engine was deleted, or both put by
  // a request that got there first)
  const put = [index && "index.html", status && "the status file"].filter(Boolean);
  if (put.length > 0) console.log(`New wiki: ${put.join(" and ")} put in the bucket`);
  return true;
}

// POST /engine/update, from the Cloudflare tab (design 1.15): index.html replaced with the empty
// wiki the worker ships, so the next page load builds the page from it, publishes the core file and
// the page for the new version and purges the public copy, as after a deletion of index.html by
// hand. The tiddlers, the plugins installed from the wiki and the published page are untouched; a
// plugin that came only with the old engine goes with it (the tab says so before). Two R2 calls:
// the engine's head, for the version it replaces, and the write. Asked for with the header every
// request of the browser modules carries, so a form on another site can't send it.
async function updateEngine(request, env, corsHeaders) {
  if (request.headers.get("X-Requested-With") !== "TiddlyWiki") return refusal("The engine is updated from the admin wiki's Cloudflare tab (" + guideText("operating", "3.3") + ").", corsHeaders);
  const html = await loadSeed();
  if (!html) return refusal(NO_SEED, corsHeaders, 404);
  const current = await env.WIKI_BUCKET.get(INDEX_KEY, { range: { offset: 0, length: 65536 } });
  const from = current ? engineVersion(await current.text()) : "";
  const to = engineVersion(html);
  await env.WIKI_BUCKET.put(INDEX_KEY, html, { httpMetadata: { contentType: "text/html; charset=utf-8" } });
  console.log(`Engine replaced: TiddlyWiki ${from || "(no version tag)"} → ${to}`);
  return new Response(JSON.stringify({ from, to }), { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json", "Cache-Control": "no-store" } });
}

const NO_SEED = "This worker was deployed without the empty wiki that would replace the engine (a deploy through Wrangler or " +
  "Workers Builds ships it, " + guideText("setup", "2.8") + "): nothing to put in place of index.html.";

// Rebuilds the page after a save or delete. If that fails (an R2 error), the change itself is
// stored: the page is marked outdated instead, so the next page load builds it (and writes any
// missing plugin file) rather than keep serving it without the change. The mark writes the same
// key the build just failed on, and R2 takes one write a second to a key: if it fails too, it's
// tried once more a second later. If that fails as well, the request fails (500), the change
// stored: the browser's retry finds what's left to do (finishSave, handleDelete).
async function rebuildPage(env, ctx, list) {
  if (await rebakeHtml(env, ctx, list)) return;
  try {
    await markPageOutdated(env);
  } catch (e) {
    console.error("Could not mark the page outdated, trying again in a second:", e.message);
    await new Promise(resolve => setTimeout(resolve, waitMs(env, 1100)));
    await markPageOutdated(env);
  }
}

const SHELL_LIMIT = 2 * 1024 * 1024;

const CORE_LIMIT = 20 * 1024 * 1024;

// An unescaped "$:/config/SaveWikiButton/Template": TiddlyWiki's own line in the core file, not a
// mention inside the core plugin's JSON
const SAVE_TEMPLATE_SETTING = /[^\\]"\$:\/config\/SaveWikiButton\/Template"/;

// PUT /page/core?v=<TiddlyWiki version>-<format>: TiddlyWiki's core file, rendered by the admin wiki
// (once per version). The same version again isn't rewritten.
async function publishCoreFile(request, env, url, corsHeaders) {
  const version = url.searchParams.get("v") || "";
  if (!/^[0-9A-Za-z.+]+(-[0-9A-Za-z.+]+)*-\d+$/.test(version)) {
    return refusal(`"${version}" isn't a core file version (<TiddlyWiki version>-<format>).`, corsHeaders);
  }
  // For the index.html the admin page was built for (X-Page-Index), as a shell: a tab opened before
  // a new one (an upgrade) would otherwise replace the core file with its older version, which the
  // public site would then serve under the new version's URL, cached for a year
  const [index, current] = await Promise.all([env.WIKI_BUCKET.head(INDEX_KEY), env.WIKI_BUCKET.head(CORE_KEY)]);
  if (!index || request.headers.get("X-Page-Index") !== index.etag) {
    return refusal("index.html has changed since this page was loaded: reload the admin wiki.", corsHeaders, 409);
  }
  if (current?.customMetadata?.v === version) return new Response(null, { status: 204, headers: corsHeaders });
  if (Number(request.headers.get("Content-Length")) > CORE_LIMIT) return refusal("The core file is too big.", corsHeaders);
  const bytes = new Uint8Array(await request.arrayBuffer());
  if (bytes.length > CORE_LIMIT) return refusal("The core file is too big.", corsHeaders);
  // It starts like TiddlyWiki's core file and ends with its boot code
  const start = pageDecoder.decode(bytes.subarray(0, charStart(bytes, Math.min(bytes.length, 8192))));
  const end = pageDecoder.decode(bytes.subarray(charStart(bytes, Math.max(0, bytes.length - 524288))));
  if (!start.startsWith("/*") || !start.includes("$tw.preloadTiddlers") || !end.includes('"$:/boot/boot.js"')) {
    return refusal("That isn't TiddlyWiki's core file.", corsHeaders);
  }
  // The admin wiki takes out TiddlyWiki's line switching the save template to the external-core one
  // (just before the boot code; the core plugin's mentions of the setting are escaped JSON). Still
  // there, TiddlyWiki has changed it: refused, so it shows, and the page stays built from index.html
  if (SAVE_TEMPLATE_SETTING.test(end)) {
    return refusal("The core file still switches the save template to the external-core one: this version of TiddlyWiki writes it in a way the page publisher doesn't know. Update the worker. Meanwhile the page is built from index.html.", corsHeaders);
  }
  await env.WIKI_BUCKET.put(CORE_KEY, bytes, {
    httpMetadata: { contentType: "application/javascript; charset=utf-8", cacheControl: "public, max-age=31536000, immutable" },
    customMetadata: { v: version }
  });
  // The page says which core file is stored (the admin wiki sends it only if it isn't): built again
  // at the next load, so it says this one even if the shell that follows is refused (otherwise every
  // load would send the core file again). Before answering, so that a shell published right after
  // builds over it. (A failure here only means the core file may be sent once more.)
  await markPageOutdated(env).catch(e => console.error("Could not mark the page outdated after a new core file:", e.message));
  return new Response(null, { status: 204, headers: corsHeaders });
}

// PUT /page/shell: the page rendered by the admin wiki, without the core. X-Page-Fingerprint: its
// fingerprint (computed by the admin wiki); X-Page-Index: the index.html the admin page was built
// for; X-Page-Shell: the stored shell the page was built from, or last published over (its ETag, ""
// when built from index.html), so a page older than the shell stored (another tab published since)
// is refused rather than replacing it, 409 with the current version in X-Page-Shell: the tab syncs
// and sends its page again, with that tab's change in it. (A tab that sends no version is from before
// this check: reload.) Refused unless it's a page that works: TiddlyWiki's tiddler store with the
// TiddlyWeb plugin, and the stored core file loaded at the end. The same shell again only makes sure
// the page is built from it. Every answer that kept or keeps a shell gives its version.
async function publishShell(request, env, ctx, corsHeaders) {
  const fingerprint = request.headers.get("X-Page-Fingerprint") || "";
  if (!fingerprint || fingerprint.length > 100) return refusal("The shell has no fingerprint (X-Page-Fingerprint).", corsHeaders);
  if (Number(request.headers.get("Content-Length")) > SHELL_LIMIT) return refusal("The shell is too big.", corsHeaders);
  const [index, core, kept] = await Promise.all([
    env.WIKI_BUCKET.head(INDEX_KEY), env.WIKI_BUCKET.head(CORE_KEY), env.WIKI_BUCKET.head(SHELL_KEY)
  ]);
  if (!index || request.headers.get("X-Page-Index") !== index.etag) {
    return refusal("index.html has changed since this page was loaded: reload the admin wiki.", corsHeaders, 409);
  }
  const withShell = (headers, shell) => ({ ...headers, "X-Page-Shell": shell });
  if (kept?.customMetadata?.index === index.etag && kept.customMetadata.fingerprint === fingerprint) {
    const page = await env.WIKI_BUCKET.head(PAGE_KEY);
    if (page?.customMetadata?.sourceEtag === index.etag && page.customMetadata.shell === fingerprint) {
      return new Response(null, { status: 204, headers: withShell(corsHeaders, kept.etag) });
    }
  }
  // The shell stored for this index.html, if any, is the one the page must have been built from
  const base = kept?.customMetadata?.index === index.etag ? kept : null;
  const sent = request.headers.get("X-Page-Shell");
  if (base && sent !== base.etag) {
    const why = sent === null ? "This page is from before the worker checked that: reload the admin wiki." : "It's sent again by itself, with that change.";
    return new Response(`Another tab published the page since this one was loaded. ${why}`, { status: 409, headers: withShell({ ...corsHeaders, "Content-Type": "text/plain; charset=utf-8" }, base.etag) });
  }
  const bytes = new Uint8Array(await request.arrayBuffer());
  if (bytes.length > SHELL_LIMIT) return refusal("The shell is too big.", corsHeaders);
  const text = pageDecoder.decode(bytes);
  if (!text.includes("<!--~~ Ordinary tiddlers ~~-->") || !text.includes('<script class="tiddlywiki-tiddler-store"')) {
    return refusal("The shell has no tiddler store.", corsHeaders);
  }
  if (!/"title":"\$:\/plugins\/tiddlywiki\/tiddlyweb"/.test(text)) {
    // Usually TiddlyWeb installed or updated from the wiki: the publisher then leaves it to its file
    return refusal("The page doesn't contain the TiddlyWeb plugin, so it couldn't sync. If TiddlyWeb was installed or updated from the wiki, delete it there and reload to go back to the one in index.html, or upload an index.html with that version.", corsHeaders);
  }
  if (!text.includes(EXTERNAL_SCRIPTS_MARKER)) return refusal("The shell has no place for the external scripts (TiddlyWiki's marker).", corsHeaders);
  const version = core?.customMetadata?.v;
  if (!version) return refusal("There's no core file yet: publish it first.", corsHeaders);
  if (!text.includes(`<script src="${coreFileUrl(env, version)}"`)) {
    return refusal(`The shell doesn't load the stored core file (${coreFileUrl(env, version)}).`, corsHeaders);
  }
  // Over the shell checked above, or none: two tabs sending at once can't both win
  const storedShell = await env.WIKI_BUCKET.put(SHELL_KEY, bytes, {
    httpMetadata: { contentType: "text/html; charset=utf-8" },
    customMetadata: { index: index.etag, fingerprint },
    onlyIf: kept ? { etagMatches: kept.etag } : new Headers({ "If-None-Match": "*" })
  });
  if (!storedShell) {
    const now = await env.WIKI_BUCKET.head(SHELL_KEY);
    return new Response("Another tab published the page at the same moment. It's sent again by itself, with that change.", { status: 409, headers: withShell({ ...corsHeaders, "Content-Type": "text/plain; charset=utf-8" }, now?.etag || "") });
  }
  const rebuilt = await untilDone(ctx, rebakeHtml(env, ctx, null, { html: bytes, index: index.etag, fingerprint, core: version, shellVersion: storedShell.uploaded.getTime(), shell: storedShell.etag }));
  if (rebuilt) return new Response(null, { status: 204, headers: withShell(corsHeaders, storedShell.etag) });
  // Kept, but the page couldn't be built now (see the logs): the next admin page load builds it
  ctx.waitUntil(markPageOutdated(env));
  return new Response("The shell is kept, but the page couldn't be rebuilt now: it will be at the next admin page load.", { status: 503, headers: withShell({ ...corsHeaders, "Content-Type": "text/plain; charset=utf-8" }, storedShell.etag) });
}

// ===== src/worker/reads.js ====================================================================================

// The reads: the TiddlyWeb status, the tiddler list, and any object of the bucket by its key (a
// tiddler, a file). design 1.1.


// What /status answers on the admin site: TiddlyWeb's status. TiddlyWiki asks for it at every page
// load, before the tiddler list. It never changes, so the browser keeps it for a week (private: for
// that browser only): the next loads don't ask the worker, nor wait for its answer. (The public site
// has its own file, setup 2.8.)
const ADMIN_STATUS = { username: "admin", read_only: false, anonymous: false, logout_is_available: true, space: { recipe: "default" } };

const STATUS_CACHE = "private, max-age=604800";

// GET /status: the same answer always, so the browser keeps it (ADMIN_STATUS)
function serveStatus(corsHeaders) {
  return new Response(JSON.stringify(ADMIN_STATUS), { headers: { ...corsHeaders, "Content-Type": "application/json", "Cache-Control": STATUS_CACHE } });
}

// GET or HEAD of an object of the bucket, by its key (already decoded): a tiddler, with its
// revision in the ETag, or anything else as stored. A browser that has it asks with that ETag
// (If-None-Match, maybe weakened to W/ by Cloudflare's compression) and is answered 304, no body:
// a file isn't even read from R2 (its ETag is R2's); a tiddler is, as its revision is in its
// metadata, and the read is the one R2 operation either way. (The admin wiki reads tiddlers from
// the public site, or has them on the device: it asks the worker for one whose public copy is
// stale or missing, and the conflict guard for the server's version. design 1.5.)
async function serveObject(request, env, key, corsHeaders) {
  if (keyTooLong(key)) return new Response("Not found", { status: 404, headers: corsHeaders });
  const tiddler = key.startsWith(TIDDLER_PREFIX);
  const known = parseEtagList(request.headers.get("If-None-Match")).filter(token => token !== "*");
  const object = await env.WIKI_BUCKET.get(key, !tiddler && known.length > 0 ? { onlyIf: { etagDoesNotMatch: known[0] } } : undefined);
  if (!object) return new Response("Not found", { status: 404, headers: corsHeaders });
  const headers = objectHeaders(object, corsHeaders);
  let unchanged = !("body" in object);   // a conditional get whose precondition failed: the browser has it
  if (tiddler) {
    // Stored with its revision, bag and recipe already in place: served as is
    const revision = revisionOf(object);
    headers.set("Cache-Control", "no-cache");
    headers.set("ETag", tiddlerEtag(key.slice(TIDDLER_PREFIX.length), revision));
    unchanged = known.includes(revision);
  } else {
    headers.set("ETag", object.httpEtag);
  }
  if (unchanged || request.method !== "GET") {
    if ("body" in object) await object.body.cancel();
    return new Response(null, { status: unchanged ? 304 : 200, headers });
  }
  return new Response(object.body, { headers });
}

// Serves the tiddler list, answering 304 when the browser already has the current version
async function serveList(request, env, ctx, corsHeaders) {
  // Our ETag is "<R2 etag>-patched"; Cloudflare's compression may hand it back weakened as W/"..."
  const known = parseEtagList(request.headers.get("If-None-Match")).find(token => token.endsWith("-patched"));
  // The admin wiki asks how backups go with this request (design 1.7): read at the same time
  const [listObject, backups] = await Promise.all([
    env.WIKI_BUCKET.get(LIST_KEY, known ? { onlyIf: { etagDoesNotMatch: known.slice(0, -"-patched".length) } } : undefined),
    request.headers.get("X-Backup-Status") === "ask" ? readBackupStatus(env) : null
  ]);
  let object = listObject;
  const listHeaders = obj => {
    const headers = listResponseHeaders(obj, corsHeaders);
    if (backups) headers.set("X-Backup-Status", backupReport(env, backups));
    return headers;
  };
  // A conditional get that fails its precondition returns the object without a body
  if (object && !("body" in object)) return new Response(null, { status: 304, headers: listHeaders(object) });

  let text = object ? await object.text() : null;
  let list = text === null ? null : parseList(text);
  // Every entry the worker writes has its bag and recipe: then the list is served as stored, not
  // written out again (which costs about as much CPU as reading it)
  if (list && list.every(t => t.bag && t.recipe)) return new Response(text, { headers: listHeaders(object) });
  if (!list) {
    // Missing or damaged: rebuilt from the stored tiddlers. (Answering [] would make every open tab
    // remove all its tiddlers as "missing from the server".)
    const rebuilt = await untilDone(ctx, rebuildList(env, ctx, { object, text }));
    // Just rebuilt: served as written (every entry already has its bag and recipe)
    if (rebuilt?.fresh) return new Response(rebuilt.text, { headers: listHeaders(rebuilt.object) });
    list = rebuilt?.entries;
    if (!list) return rebuildingResponse(corsHeaders);
    object = rebuilt.object;
  }
  // Written by hand, say
  list = list.map(t => ({ ...t, bag: t.bag || "default", recipe: t.recipe || "default" }));
  return new Response(JSON.stringify(list), { headers: listHeaders(object) });
}

function listResponseHeaders(object, corsHeaders) {
  const headers = objectHeaders(object, corsHeaders);
  headers.set("Cache-Control", "no-cache");
  headers.set("ETag", `"${object.etag}-patched"`);
  return headers;
}

// ===== src/worker/saves.js ====================================================================================

// Saves and deletes (design 1.4): the precondition check, the conditional write, the list update,
// the purge, the backup, and the page and plugin file when the tiddler is one the page needs.


// PUT recipes/default/tiddlers/<title>: a save (design 1.4)
async function handleSave(request, env, ctx, url, corsHeaders) {
  try {
    const match = url.pathname.match(/^\/recipes\/default\/tiddlers\/(.+)$/);
    if (!match) return new Response("Invalid PUT path", { status: 400, headers: corsHeaders });

    const title = decodePath(match[1]);
    if (title === null) return invalidPath(corsHeaders);
    let save = await readSave(request);
    // Stored and listed under the title in the URL: a different one in the body would make the
    // list disagree with the stored tiddlers (the browser always sends the same one)
    if (save.fields.title !== title) throw new BadSave("the title in the body isn't the one in the URL");

    if (isEphemeralTitle(title) || isDraft(save.fields)) {
      return savedResponse(title, Date.now().toString(), corsHeaders);
    }
    if (keyTooLong(tiddlerKey(title))) {
      throw new BadSave(`the title is too long: R2 keys hold at most ${MAX_KEY_BYTES - TIDDLER_PREFIX.length} bytes of it (UTF-8)`);
    }

    // The stored tiddler and the tiddler list, read at once (one round trip, not two). While a
    // damaged list is being rebuilt, readableList throws: the save is refused (503) without
    // changing anything, so the browser's retry can't conflict with it.
    // (A save without its text, keepStoredText, reads the stored text too.)
    const key = tiddlerKey(title), skinny = Object.hasOwn(save.fields, "_is_skinny");
    const [current, list] = await Promise.all([skinny ? env.WIKI_BUCKET.get(key) : env.WIKI_BUCKET.head(key), readableList(env, ctx)]);
    const currentRevision = current ? revisionOf(current) : null;
    if (skinny) save = await keepStoredText(save, current);

    const { conditional, reason } = checkPreconditions(request, currentRevision);
    if (reason) {
      // A retry of a save that was stored but whose list update then failed: the stored tiddler
      // is exactly what this save would store, so finish that save instead of refusing it.
      // (Otherwise the browser sees the identical copy, adopts it, and the list is never fixed.)
      if (current && await storesSameContent(env, current, save, currentRevision)) {
        await untilDone(ctx, finishSave(env, ctx, title, save.fields, currentRevision, list, url.origin, true));
        return savedResponse(title, currentRevision, corsHeaders);
      }
      // The stored tiddler isn't the version the list has: a save whose list update failed, retried
      // with other content (edited again since) or not at all (its tab closed). Refused all the same,
      // since it isn't based on that version (only the conflict guard can tell its own save, design
      // 1.4), but that save is finished: the list, the public cache and the page catch up with it.
      if (current && listedRevision(list, title) !== currentRevision) {
        const fields = await storedFields(env, current);
        if (fields) await untilDone(ctx, finishSave(env, ctx, title, fields, currentRevision, list, url.origin, true));
      }
      return conflictResponse(title, reason, currentRevision, corsHeaders);
    }

    const newRevision = Date.now().toString();
    const body = save.stored(newRevision);
    const putOptions = {
      httpMetadata: { contentType: "application/json" },
      customMetadata: { revision: newRevision, layout: FLAT_LAYOUT }
    };

    if (conditional) {
      // Only write if the object is still exactly the one we checked (or still absent)
      let written = await env.WIKI_BUCKET.put(key, body, {
        ...putOptions,
        onlyIf: current ? { etagMatches: current.etag } : new Headers({ "If-None-Match": "*" })
      });
      if (written === null && !current && !(await env.WIKI_BUCKET.head(key))) {
        // A create-only write was refused but nothing is there: write it normally
        written = await env.WIKI_BUCKET.put(key, body, putOptions);
      }
      if (written === null) {
        const latest = await env.WIKI_BUCKET.head(key);
        return conflictResponse(title, "it was changed in another tab or browser", latest ? revisionOf(latest) : null, corsHeaders);
      }
    } else {
      await env.WIKI_BUCKET.put(key, body, putOptions);
    }

    ctx.waitUntil(queueBackup(env, { action: "save", title, revision: newRevision, content: body }));
    await untilDone(ctx, finishSave(env, ctx, title, save.fields, newRevision, list, url.origin));

    return savedResponse(title, newRevision, corsHeaders);
  } catch (error) {
    return failureResponse("Save failed", error, corsHeaders);
  }
}

// DELETE bags/<bag>/tiddlers/<title> (or recipes/<recipe>/...): a delete (design 1.4)
async function handleDelete(request, env, ctx, url, corsHeaders) {
  try {
    const match = url.pathname.match(/^\/(?:bags|recipes)\/[^/]+\/tiddlers\/(.+)$/);
    if (!match) return new Response("Invalid DELETE path", { status: 400, headers: corsHeaders });

    const title = decodePath(match[1]);
    if (title === null) return invalidPath(corsHeaders);
    // The story list, state and temp tiddlers are never stored, nor a title too long for a key,
    // so there is nothing to delete or back up
    if (isEphemeralTitle(title) || keyTooLong(tiddlerKey(title))) return new Response(null, { status: 204, headers: corsHeaders });

    // Read first, like a save (see there). The check below is then followed at once by the
    // delete, which can't be made conditional.
    const list = await readableList(env, ctx);
    const found = await env.WIKI_BUCKET.head(tiddlerKey(title));
    let currentRevision;
    if (found) {
      currentRevision = revisionOf(found);
      const { reason } = checkPreconditions(request, currentRevision);
      if (reason) return conflictResponse(title, reason, currentRevision, corsHeaders);
      await env.WIKI_BUCKET.delete(found.key);
    }
    // Queued before the list update, which may fail (the retry then finds nothing to delete)
    if (found) ctx.waitUntil(queueBackup(env, { action: "delete", title, revision: currentRevision }));
    await untilDone(ctx, (async () => {
      // If it was neither stored nor listed, there is nothing to back up or purge
      let { removed, list: stored, recreated } = await removeFromList(env, ctx, title, list, found ? currentRevision : null);
      if (recreated) {
        // Saved again since: that save's purge, plugin file and page build are the ones. Unless that
        // save landed between the check above and the delete, which then removed it too (an R2
        // delete can't be conditional): nothing is stored, so the entry goes as well
        if (await env.WIKI_BUCKET.head(tiddlerKey(title))) return;
        ({ removed, list: stored } = await removeFromList(env, ctx, title, stored));
      }
      if (!found && removed) ctx.waitUntil(queueBackup(env, { action: "delete", title, revision: currentRevision }));
      if (found || removed) ctx.waitUntil(purgePublicCache(env, tiddlerPurgeUrls(env, title, url.origin)));
      // Neither stored nor listed: a retry of a delete that failed after both were done, whose page
      // build failed and was never marked outdated (rebuildPage): the plugin file is the only trace left
      const leftover = !found && !removed && !!(await env.WIKI_BUCKET.head(pluginFileKey(title)));
      // The list entry says what it was; if it wasn't listed, rebuild the page for system tiddlers,
      // and delete any plugin file anyway (deleting a missing object is free), once the page is
      // rebuilt without it (see deletePluginFile)
      if (removed ? isPageTiddler(removed) : (found && title.startsWith("$:/")) || leftover) {
        await rebuildPage(env, ctx, stored);
      }
      if (removed ? needsPluginFile(removed) : found || leftover) await deletePluginFile(env, title);
    })());

    return new Response(null, { status: 204, headers: corsHeaders });
  } catch (error) {
    return failureResponse("Delete failed", error, corsHeaders);
  }
}

// The rest of a save once the tiddler is stored: the tiddler list, the public cache and the page.
// list: the list as read before the tiddler was stored (readableList), or null to read it here.
// adminOrigin: the admin site's origin (where this request came to), see tiddlerPurgeUrls.
// retried: this is a save sent again (its first answer lost, or its list update failed): the list
// may already say what it would say, so what's left of the first attempt is found another way.
async function finishSave(env, ctx, title, fields, revision, list, adminOrigin, retried = false) {
  const { previous, list: stored, superseded, gone } = await updateList(env, ctx, title, fields, revision, list);
  // A newer save of this tiddler got there first, or a delete removed it meanwhile: that request's
  // purge, plugin file and page build are the ones
  if (superseded || gone) return;
  // Only once the new list is in R2: a public request between the purge and the list update
  // would put the old list back in Cloudflare's cache
  ctx.waitUntil(purgePublicCache(env, tiddlerPurgeUrls(env, title, adminOrigin)));
  const saved = { ...fields, title };
  const wasPlugin = previous && needsPluginFile(previous);
  // A plugin saved as an ordinary tiddler, whose page build failed and was never marked outdated:
  // the retry's list already has the ordinary tiddler, and the file is the only trace left
  const leftover = retried && !wasPlugin && !needsPluginFile(saved) && !!(await env.WIKI_BUCKET.head(pluginFileKey(title)));
  // Something the page needs at boot was added, changed or is no longer needed: rebuild the
  // page (which writes the plugin file) before confirming, so a reload right after has it
  if (isPageTiddler(saved) || (previous && isPageTiddler(previous)) || leftover) {
    await rebuildPage(env, ctx, stored);
  }
  // No longer a plugin: its file goes, now that the page doesn't load it
  if ((wasPlugin || leftover) && !needsPluginFile(saved)) await deletePluginFile(env, title);
}

// ===== src/worker/setup.js ====================================================================================

// The setup check (design 1.13): GET /setup/check, from the control panel's Cloudflare tab, looks at
// each piece of the setup that's done by hand and says what it found, a missing or wrong one naming
// the section of the setup guide that fixes it, with its link (docs.js). Nothing says these things
// otherwise: the page's own requests work without the CORS header, and a missing rewrite rule shows
// only to visitors. On demand only. A line that finds a piece missing or wrong ends with the one
// thing to do (the dashboard's place, the setting, the rule), before the guide's section with the
// full steps: the manual is a click away, the next step shouldn't be (design 2.20).
//
// From here: Access (this request came through it); the public site as the worker sees it from its
// own requests — the page at / (the rewrite rule, checked by ETag against the stored page: one R2
// head, no body read), the tiddler list and the core file asked for with the admin site as Origin
// (the CORS rule, each of its two paths), the status file, and what Cloudflare's cache answered for
// each (the cache rules, optional); backups (GitHub asked for the repository and its branch with
// the token) and the queue binding; purges (one purge, of the status file's cached copy: a token
// allowed only to purge can't be tested another way). The browser adds its own lines (the service
// worker, the core file kept) in the tab, $:/cfworker/control-panel.js.
//
// Each line: { id, ok: true | false | null (nothing to check, or optional), text, guide: { section,
// text ("setup 2.6"), url } }.


const SECTION = { private: "2.1", site: "2.2", queue: "2.3", backups: "2.4", worker: "2.5", access: "2.6", rules: "2.7" };
const PUBLIC_IDS = ["public", "rewrite", "cors-reads", "cors-files", "cache"];
// The public site's five pieces by name, one line per piece as on a public wiki, each naming the piece
// it stands for, on a private wiki (nothing to check) and when the site doesn't answer (not checked):
// one sentence five times read as a loop gone wrong
const PIECE = { "public": "The public site", "rewrite": "The rewrite rule", "cors-reads": "The CORS rule, tiddler reads", "cors-files": "The CORS rule, files", "cache": "The cache rules" };
const privateLine = id => `${PIECE[id]}: ${id === "public" ? "a private wiki has none" : "no public site"}, nothing to check.`;
const uncheckedLine = id => `${PIECE[id]}: not checked, the public site didn't answer.`;
// Where the worker's settings are set, in every line that names one
const VARS = "in the worker's Variables and Secrets";
// GitHub's page for a fine-grained token: its permissions and the repositories it may see
const TOKENS = "Settings → Developer settings → Personal access tokens → Fine-grained tokens";
// What Cloudflare's cache answered for a path a cache rule covers (DYNAMIC: none does)
const CACHED = ["HIT", "MISS", "EXPIRED", "STALE", "UPDATING", "REVALIDATED"];

async function setupCheck(request, env, ctx, corsHeaders) {
  const origin = new URL(request.url).origin;
  const checks = [];
  const add = (id, ok, text, section) => checks.push({ id, ok, text, guide: guide("setup", section) });

  add("access", true, ctx.access
    ? "Cloudflare Access protects the admin site: this request came through it."
    : "Cloudflare Access is off for this local address (ACCESS = off, for tests and local runs only): a deployed worker refuses every request that didn't come through Access.", SECTION.access);

  const site = publicSite(env);
  if (site) {
    await checkPublicSite(env, site, origin, add);
  } else {
    for (const id of PUBLIC_IDS) add(id, null, privateLine(id), SECTION.private);
  }
  await checkBackups(env, add);
  add("queue", !!env.BACKUP_QUEUE, env.BACKUP_QUEUE
    ? "The backup queue is bound (BACKUP_QUEUE): saves are queued for backup, and a full backup can run."
    : "The backup queue isn't bound: the worker was deployed without BACKUP_QUEUE, so nothing can be queued for backup. Deploy it with the queue wrangler.toml names.", SECTION.queue);
  await checkPurges(env, site, add);

  return new Response(JSON.stringify({ checked: new Date().toISOString(), checks }), {
    headers: { ...corsHeaders, "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" }
  });
}

// One request to the public site, with the admin site as Origin when asked: what came back, by
// its headers. The body is dropped unread, unless the caller keeps it (keep) to read it itself.
async function probe(url, origin, keep) {
  try {
    const res = await fetch(url, { headers: origin ? { Origin: origin } : {}, redirect: "follow" });
    const h = name => res.headers.get(name);
    if (!keep && res.body) await res.body.cancel();
    return { status: res.status, etag: h("ETag"), lastModified: h("Last-Modified"), allowOrigin: h("Access-Control-Allow-Origin"), cache: h("CF-Cache-Status"), type: h("Content-Type"), res: keep ? res : null };
  } catch (e) {
    return { error: e && e.message ? e.message : String(e) };
  }
}

const bareEtag = etag => (etag || "").replace(/^W\//, "").replace(/^"|"$/g, "");
const seconds = date => Math.floor((date instanceof Date ? date.getTime() : Date.parse(date || "")) / 1000);
// What every page the worker builds carries: its own tiddlers (build.js)
const PAGE_MARK = "$:/cfworker/";

// What the public site's / is: the stored page ("current"), known by ETag when the answer has one
// (bare of W/ and quotes: Cloudflare's compression weakens it), else by date (Last-Modified against
// the object's upload time: Cloudflare removes an HTML answer's ETag when a feature of the zone
// rewrites the page, Email Address Obfuscation say, on by default, but keeps the date); failing
// those, by the page's own mark in the body, read only then: with neither header, the page
// ("current", nothing says otherwise), and with a header that doesn't match, an earlier build of it
// ("earlier": Cloudflare's cached copy, the page rebuilt since, purged at the next save or expiring
// with the cache rule's TTL), which is the wiki page too, so the rule is in place; or not the page
// at all (false)
async function whichPage(page, stored) {
  if (page.status !== 200 || !stored) return false;
  const headed = !!(page.etag || page.lastModified);
  if (page.etag && bareEtag(page.etag) === bareEtag(stored.httpEtag)) return "current";
  if (!page.etag && page.lastModified && seconds(page.lastModified) === seconds(stored.uploaded)) return "current";
  try {
    return (await page.res.text()).includes(PAGE_MARK) ? (headed ? "earlier" : "current") : false;
  } catch {
    return false;
  }
}

async function checkPublicSite(env, site, origin, add) {
  const host = new URL(site).host;   // (PUBLIC_WIKI_URL is checked before any request is handled: a URL)
  const [page, list, core, status, stored] = await Promise.all([
    probe(publicUrl(env, "/"), null, true),
    probe(publicUrl(env, "/" + LIST_KEY), origin),
    probe(publicUrl(env, "/" + CORE_KEY), origin),
    probe(publicUrl(env, "/" + STATUS_KEY), null),
    env.WIKI_BUCKET.head(PAGE_KEY)
  ]);
  // (A site that's down answers through Cloudflare's edge, a 5xx page, as often as not at all)
  if (page.error || page.status >= 500) {
    add("public", false, `The public site at ${site} didn't answer (${page.error || `answered ${page.status}`}): no bucket answers at PUBLIC_WIKI_URL. Connect the domain to the bucket (R2 → the bucket → Settings → Custom Domains, which creates its DNS record and turns public access on for it) and set PUBLIC_WIKI_URL, ${VARS}, to https:// and that domain, nothing after the hostname.`, SECTION.site);
    for (const id of PUBLIC_IDS.slice(1)) add(id, null, uncheckedLine(id), SECTION.site);
    return;
  }
  add("public", true, `The public site answers at ${site}.`, SECTION.site);
  const which = await whichPage(page, stored);
  if (page.res && page.res.body && !page.res.bodyUsed) await page.res.body.cancel().catch(() => {});
  if (which === "current") {
    add("rewrite", true, "The public site's / serves the wiki page (the rewrite rule / → /baked.html).", SECTION.rules);
  } else if (which === "earlier") {
    add("rewrite", true, "The public site's / serves the wiki page (the rewrite rule / → /baked.html), an earlier build of it: Cloudflare's cached copy, purged at the next save, or when the cache rule's TTL runs out.", SECTION.rules);
  } else {
    const found = `answered ${page.status}, ${page.etag ? `ETag ${page.etag}` : "no ETag"}, ${page.lastModified ? `Last-Modified ${page.lastModified}` : "no Last-Modified"}`;
    const known = stored ? `the stored page's are "${bareEtag(stored.httpEtag)}" and ${stored.uploaded.toUTCString()}` : "the page isn't built yet";
    add("rewrite", false, `The public site's / doesn't serve the wiki page (${found}; ${known}): the rewrite rule / → /baked.html is missing or wrong. Add it under the domain, Rules → Transform Rules → Rewrite URL: when the host is ${host} and the path is /, rewrite the path to /baked.html.`, SECTION.rules);
  }
  const allowed = r => !r.error && (r.allowOrigin === origin || r.allowOrigin === "*");
  const found = r => r.error ? `no answer: ${r.error}` : r.allowOrigin ? `Access-Control-Allow-Origin: ${r.allowOrigin}` : "no Access-Control-Allow-Origin header";
  add("cors-reads", allowed(list),
    allowed(list) ? "The CORS rule lets the admin site read tiddlers from the public site (/recipes/)."
      : `The public site's tiddlers (/recipes/) can't be read from the admin site, ${origin} (${found(list)}): the CORS rule is missing or doesn't cover /recipes/; tiddlers load through the worker meanwhile, a request each. Add or fix the rule under the domain, Rules → Transform Rules → Modify Response Header: when the host is ${host} and the path starts with /recipes/ or /_plugins/, set Access-Control-Allow-Origin to ${origin}.`, SECTION.rules);
  add("cors-files", allowed(core),
    allowed(core) ? "The CORS rule lets the admin site keep the core and plugin files for opening offline (/_plugins/)."
      : `The public site's core and plugin files (/_plugins/) can't be kept by the admin site, ${origin} (${found(core)}): the CORS rule doesn't cover /_plugins/; the wiki runs online as before, and doesn't open offline on a device that doesn't have them. Add the path to the rule's When, under the domain's Rules → Transform Rules → Modify Response Header: the host is ${host} and the path starts with /recipes/ or /_plugins/.`, SECTION.rules);
  const cached = r => !r.error && CACHED.includes(String(r.cache || "").toUpperCase());
  const say = r => r.error ? "no answer" : r.cache || "no CF-Cache-Status header";
  const all = cached(page) && cached(core) && cached(status);
  // The setup guide's rule for each path, named when the path isn't cached (2.7: the second and
  // third are placed after the first, which covers the whole host)
  const rules = [!cached(page) && '"Cache public wiki" for the page', !cached(core) && '"Cache plugin files" for the core and plugin files', !cached(status) && '"Cache status file" for the status file'].filter(Boolean);
  add("cache", all ? true : null,
    `Cloudflare's cache answered for the page: ${say(page)}, the core file: ${say(core)}, the status file: ${say(status)}.` +
      (all ? "" : ` DYNAMIC, or no header, means no cache rule covers it, and the public site goes to the bucket for it at every request. To cache it (optional), add under the domain's Rules → Cache Rules: ${rules.join(", ")}.`), SECTION.rules);
}

async function checkBackups(env, add) {
  const gh = github(env);
  if (!gh) {
    const has = env.GITHUB_REPO ? `GITHUB_REPO (${env.GITHUB_REPO}) but no GITHUB_TOKEN` : env.GITHUB_TOKEN ? "GITHUB_TOKEN but no GITHUB_REPO" : "no GITHUB_REPO and no GITHUB_TOKEN";
    const todo = env.GITHUB_REPO ? `Make a fine-grained token limited to that repository, with Contents read and write, and put it in the GITHUB_TOKEN secret, ${VARS}.`
      : env.GITHUB_TOKEN ? `Set GITHUB_REPO, ${VARS}, to the backup repository's owner/repo, the one the token is limited to.`
        : `Create a repository for the backup and a fine-grained token limited to it, with Contents read and write, then set GITHUB_REPO (owner/repo) and the GITHUB_TOKEN secret ${VARS}.`;
    add("backups", false, `Backups aren't set up: the worker has ${has} (optional; with ${env.GITHUB_REPO || env.GITHUB_TOKEN ? "it" : "them"}, every save is committed to GitHub). ${todo}`, SECTION.backups);
    return;
  }
  const headers = { Authorization: `Bearer ${gh.token}`, Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "TiddlyWiki-Cloudflare-Worker" };
  const ask = async path => {
    try {
      const res = await fetch(`https://api.github.com/repos/${gh.repo}${path}`, { headers });
      let message = "";
      try { message = String((await res.json()).message || ""); } catch {}
      return { status: res.status, message };
    } catch (e) {
      return { status: 0, message: e && e.message ? e.message : String(e) };
    }
  };
  const repo = await ask("");
  if (repo.status === 401) {
    add("backups", false, `GitHub refuses the token for ${gh.repo} (401${repo.message ? `, ${repo.message}` : ""}): the GITHUB_TOKEN secret is wrong or has expired. Make a new one and put it in the secret.`, SECTION.backups);
  } else if (repo.status === 404) {
    add("backups", false, `GitHub doesn't find ${gh.repo} with this token (404): the repository doesn't exist under that name, or the token isn't allowed to see it. Check GITHUB_REPO (owner/repo, as in the repository's address), then the token's Repository access on GitHub (${TOKENS}): it must name that repository.`, SECTION.backups);
  } else if (repo.status !== 200) {
    add("backups", false, `GitHub answered ${repo.status || "nothing"} for ${gh.repo}${repo.message ? ` (${repo.message})` : ""}. Check the setup again in a moment: a rate limit, or no answer, passes by itself; an answer that stays is GitHub's reason, and the token's permissions (Contents: read and write) and Repository access, on GitHub under ${TOKENS}, are where to look.`, SECTION.backups);
  } else {
    const branch = await ask(`/branches/${encodeURIComponent(gh.branch)}`);
    if (branch.status === 200) {
      add("backups", true, `Backups go to ${gh.repo}, branch ${gh.branch}: GitHub accepts the token. (Whether it may write there shows at the first save; this tab reports backups that fail.)`, SECTION.backups);
    } else {
      add("backups", false, `GitHub finds ${gh.repo} but not its branch ${gh.branch} (${branch.status}${branch.message ? `, ${branch.message}` : ""}): the repository has no such branch, or is empty. Set GITHUB_BRANCH, ${VARS}, to a branch it has (main when GITHUB_BRANCH isn't set), or give an empty repository its first commit (a README added on GitHub does).`, SECTION.backups);
    }
  }
}

async function checkPurges(env, site, add) {
  if (!site) {
    add("purges", null, "A private wiki: nothing to purge.", SECTION.private);
    return;
  }
  const zone = purges(env);
  if (!zone) {
    const missing = env.CF_ZONE_ID ? "CF_API_TOKEN isn't set (CF_ZONE_ID is)" : env.CF_API_TOKEN ? "CF_ZONE_ID isn't set (CF_API_TOKEN is)" : "CF_ZONE_ID and CF_API_TOKEN aren't set";
    const todo = env.CF_ZONE_ID ? `set the CF_API_TOKEN secret, ${VARS}: a token from My Profile → API Tokens with Zone → Cache Purge on that zone.`
      : env.CF_API_TOKEN ? `set CF_ZONE_ID, ${VARS}, to the zone ID on the domain's overview page.`
        : `set CF_ZONE_ID (the zone ID on the domain's overview page) and the CF_API_TOKEN secret (a token from My Profile → API Tokens with Zone → Cache Purge on that zone) ${VARS}.`;
    add("purges", null, `No purges: ${missing}, so a change shows on the public site when its cached copy expires (optional). To purge, ${todo}`, SECTION.worker);
    return;
  }
  try {
    const res = await fetch(`https://api.cloudflare.com/client/v4/zones/${zone.zoneId}/purge_cache`, {
      method: "POST", headers: { Authorization: `Bearer ${zone.token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ files: [publicUrl(env, "/" + STATUS_KEY)] })
    });
    let body = null;
    try { body = await res.json(); } catch {}
    if (res.ok && body && body.success) {
      add("purges", true, "Purges work: the public site's status file was purged from Cloudflare's cache to check (CF_ZONE_ID, CF_API_TOKEN).", SECTION.worker);
    } else {
      const message = body && Array.isArray(body.errors) && body.errors.length ? body.errors.map(e => e.message).join("; ") : "";
      add("purges", false, `Cloudflare refused the purge (${res.status}${message ? `: ${message}` : ""}): CF_API_TOKEN needs Zone → Cache Purge on the zone CF_ZONE_ID names. Check CF_ZONE_ID against the zone ID on the domain's overview page, and the token under My Profile → API Tokens (its permissions, its zone, whether it has expired or was revoked); a new token there, put in the CF_API_TOKEN secret, replaces it.`, SECTION.worker);
    }
  } catch (e) {
    add("purges", false, `Cloudflare's API didn't answer the purge (${e && e.message ? e.message : e}): the request to api.cloudflare.com failed before any answer. Check the setup again in a moment; if it keeps failing, see cloudflarestatus.com.`, SECTION.worker);
  }
}

// ===== src/worker/index.js ====================================================================================

// TiddlyWiki on Cloudflare: the admin worker. The entry point: the request router, and the queue
// consumer. See README.md for the whole picture, and design 1.1 for the requests answered here.
//
// Every request goes: Access check → settings check → the route whose method and path match. The
// modules, from the bottom up: docs (where the manual is, for messages), bytes, tiddlers, storage,
// settings, access, http (the small shared helpers); layout (reading and storing a tiddler), cache
// (public site purges), list (the tiddler list and its rebuild), plugins (plugin files), app (the
// app's manifest and icons), build (building the page), page (serving and publishing it); reads and
// saves (the handlers); backup/ (the GitHub backup through the queue); setup (the setup check).
// Each imports only from the ones before it (build.mjs refuses a cycle).
//
// worker.js is built from these by `npm run build` (build.mjs), with the browser modules of
// src/browser/ embedded as text (build.js lists them).


// The admin wiki is served by this worker and talks to it from its own origin (its reads of the
// public site are allowed there, by the zone's CORS rule, setup 2.7); these headers let a page from
// elsewhere talk to it too. "*" gives nothing away: Access answers before the worker, and a browser
// shows a page from another site no response it asked for with credentials when the origin allowed
// is "*" (credentials need a named one), so such a page gets either a refusal or nothing. TiddlyWiki
// reads the ETag of each save, which a browser only shows a page that's told it may (Expose-Headers).
const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, PUT, POST, DELETE, OPTIONS, HEAD",
  "Access-Control-Allow-Headers": "Content-Type, X-Requested-With, X-Tiddler-Layout, If-Match, If-None-Match, Accept",
  "Access-Control-Expose-Headers": "ETag, X-Tiddler-List, Retry-After",
};

const PAGE_PATHS = ["/", "/index.html", "/baked.html"];

// The routes, in the order they're tried: { methods, matches(path) → what the handler gets (false:
// not this route; null: a path that isn't valid percent-encoding, 400), handle(...) }
const ROUTES = [
  { methods: ["OPTIONS"], matches: () => true, handle: (request, env, ctx, url, match, headers) => new Response(null, { headers }) },
  { methods: ["GET"], matches: path => path === "/status", handle: (request, env, ctx, url, match, headers) => serveStatus(headers) },
  { methods: ["GET"], matches: path => path === "/sw.js", handle: (request, env, ctx, url, match, headers) => serveServiceWorker(request, headers) },
  { methods: ["GET"], matches: path => path === `/${MANIFEST_KEY}`, handle: (request, env, ctx, url, match, headers) => serveManifest(env, headers) },
  { methods: ["GET"], matches: path => { const m = path.match(/^\/_app\/icon-(\d+)\.png$/); return m && APP_ICON_SIZES.includes(Number(m[1])) ? Number(m[1]) : false; }, handle: (request, env, ctx, url, size, headers) => serveIcon(env, size, headers) },
  { methods: ["GET"], matches: path => PAGE_PATHS.includes(path), handle: (request, env, ctx, url, match, headers) => serveWiki(request, env, ctx, headers) },
  // A full backup (design 1.7): started by the admin wiki, and how the last one went
  { methods: ["POST"], matches: path => path === "/backup/sync", handle: (request, env, ctx, url, match, headers) => startBackupSync(request, env, ctx, headers) },
  { methods: ["GET"], matches: path => path === "/backup/sync", handle: (request, env, ctx, url, match, headers) => backupSyncStatus(env, headers) },
  // The setup check (design 1.13): each piece of the setup looked at, on demand
  { methods: ["GET"], matches: path => path === "/setup/check", handle: (request, env, ctx, url, match, headers) => setupCheck(request, env, ctx, headers) },
  { methods: ["POST"], matches: path => path === "/engine/update", handle: (request, env, ctx, url, match, headers) => updateEngine(request, env, headers) },
  // Any other read is an object of the bucket, by its key: the tiddler list, a tiddler, a file
  { methods: ["GET", "HEAD"], matches: path => decodePath(path.substring(1)), handle: (request, env, ctx, url, key, headers) =>
    key === LIST_KEY ? serveList(request, env, ctx, headers) : serveObject(request, env, key, headers) },
  { methods: ["PUT"], matches: path => path === "/page/core", handle: (request, env, ctx, url, match, headers) => publishCoreFile(request, env, url, headers) },
  { methods: ["PUT"], matches: path => path === "/page/shell", handle: (request, env, ctx, url, match, headers) => publishShell(request, env, ctx, headers) },
  { methods: ["PUT"], matches: () => true, handle: (request, env, ctx, url, match, headers) => handleSave(request, env, ctx, url, headers) },
  { methods: ["DELETE"], matches: () => true, handle: (request, env, ctx, url, match, headers) => handleDelete(request, env, ctx, url, headers) },
];

const plainText = (text, status) => new Response(text, { status, headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" } });

export default {
  async fetch(request, env, ctx) {
    // Before anything else: a request Access didn't authenticate costs nothing but this answer
    if (withoutAccess(request, ctx, env)) return plainText(ACCESS_REFUSED, 403);
    const url = new URL(request.url);
    // Nor anything with a public address that isn't a site's (the page would load its code from
    // nowhere); none at all is a private wiki
    const notSetUp = publicSiteError(env, url.origin);
    if (notSetUp) return plainText(notSetUp, 500);

    for (const route of ROUTES) {
      if (!route.methods.includes(request.method)) continue;
      const match = route.matches(url.pathname);
      if (match === null) return invalidPath(CORS_HEADERS);
      if (match === false) continue;
      return route.handle(request, env, ctx, url, match, CORS_HEADERS);
    }
    return new Response("Method not allowed", { status: 405, headers: CORS_HEADERS });
  },

  // Queue consumer: commits queued saves and deletes to GitHub, one at a time
  async queue(batch, env) {
    await processBackupBatch(batch, env);
  }
};
